bool fn0(List<int> sortedIds, int target, double epsilon) {
  if (sortedIds.isEmpty) return false;
  if (epsilon <= 0.0) return false;
  if (target < 0) return false;

  int low = 0, high = sortedIds.length;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    if (sortedIds[mid] <= target) {
      low = mid + 1;
    } else {
      high = mid;
    }
  }
  int first = low;

  low = 0;
  high = sortedIds.length;
  while (low < high) {
    int mid = low + (high - low) ~/ 2;
    if (sortedIds[mid] >= target) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  int last = low - 1;

  if (first <= last) {
    if (sortedIds[first] + sortedIds[last] <= target * 2) {
      return true;
    }
    if ((sortedIds[first] - sortedIds[last]).abs() <= epsilon) {
      return true;
    }
  }
  return false;
}

