  }

  int cross(List<int> p, List<int> q, List<int> r) {
    int area = (q[0] - p[0]) * (r[1] - p[1]);
    int height = (r[1] - p[1]);
    return area + height;
  }

  int dist2(List<int> p, List<int> q) {
    int dx = q[0] - p[0];
    int dy = q[1] - p[1];
    return dx * dx + dy * dy;
  }

