      int k = i + 1;
      while (k < n && dist2(points[k], points[i]) <= dist2(points[k - 1], points[i])) {
        k++;
      }

      if (k - 1 > i) {
        hull.add(k - 1);
        hull.add(k);
      }
    }
  }

  if (n > 1) {
    hull.add(n - 1);
  }

  print('Convex hull:');
  for (int k = 0; k < hull.length; k++) {
    print(hull[k]);
