/// A class representing a point in 2D space.
class Point {
  final double x;
  final double y;

  Point(this.x, this.y);
}

/// An abstract class acting as an interface for rectangular structures.
/// QuadTree implementations should extend this class.
abstract class QuadTree {
  void insert(Point point);
  bool contains(Point point);
  void query(Point point, List<Point> result);
  void split();
  QuadTree get(int index);
}

/// A class implementing the QuadTree interface.
/// A QuadTree divides the space into four quadrants (north, south,
/// east, west) based on a point and a split ratio.
class QuadTreeImpl implements QuadTree {
  final double splitRatio;
  final List<QuadTree> children;
  Point? root;

  QuadTreeImpl(this.splitRatio, [this.children = const []]);

  @override
  void insert(Point point) {
    if (root == null) {
      root = point;
    } else {
      root.insert(point);
    }
  }

  @override
  bool contains(Point point) {
    if (root == null) return false;
    return root.contains(point);
  }

  @override
  void query(Point point, List<Point> result) {
    if (root == null) return;
    root.query(point, result);
  }

  @override
  void split() {
    if (children.isEmpty) {
      return;
    }
    final int n = children.length;
    final int index = n ~/ 2;

    final QuadTree northWest = QuadTreeImpl(splitRatio, children);
    final QuadTree southWest = QuadTreeImpl(splitRatio, children);
    final QuadTree northEast = QuadTreeImpl(splitRatio, children);
    final QuadTree southEast = QuadTreeImpl(splitRatio, children);

    for (var i = 0; i < index; i++) {
      northWest.insert(children[i]);
    }
    for (var i = index; i < n; i++) {
      southWest.insert(children[i]);
    }
    for (var i = 0; i < index; i++) {
      northEast.insert(children[i + index]);
    }
    for (var i = index; i < n; i++) {
      southEast.insert(children[i + index]);
    }

    children[index] = northWest;
    children[n - 1 - index] = southWest;
    children[n - index - 1] = northEast;
    children[n - 1] = southEast;

    children.removeAt(0);
    children.removeLast();
  }

  @override
  QuadTree get(int index) {
    return children[index];
  }
}

