bool fn0(List<int> diceValues, int target, int minRolls, int maxRolls) {
  int count = 0;
  int sum = 0;

  void backtrack(int index) {
    if (index >= minRolls) {
      if (sum >= target) {
        count++;
      }
      return;
    }
    for (int i = index; i < diceValues.length; i++) {
      final int val = diceValues[i];
      if (val > 0) {
        sum += val;
        backtrack(i + 1);
        sum -= val;
      }
    }
  }

  backtrack(0);
  return count <= maxRolls;
}

