/// Abstract class acting as an interface for rating prediction models.
abstract class RatingPredictionModel {
  /// Predicts the rating for the specified user and item.
  double predictRating(int userId, int itemId);
}

/// Class implementing the RatingPredictionModel interface.
class CollaborativeFilteringModel implements RatingPredictionModel {
  final List<List<double>> ratings;
  final int k;

  CollaborativeFilteringModel(this.ratings, this.k);

  @override
  double predictRating(int userId, int itemId) {
    if (ratings.isEmpty || k <= 0) {
      return double.nan;
    }

    double sum = 0.0;
    int count = 0;

    for (int i = 0; i < ratings.length; i++) {
      if (ratings[i][itemId] != 0.0) {
        sum += ratings[i][userId];
        count++;
      }
    }

    if (count == 0) {
      return double.nan;
    }

    double avg = sum / count;

    return avg;
  }
}

