    }
    double normA = math.sqrt(sum * sum);
    if (normA == 0) return 0.0;
    double normB = math.sqrt(sum * sum);
    if (normB == 0) return 0.0;
    return sum / (normA * normB);
  }

  double predictRating(int u, int i, List<List<double>> ratings, List<double> userSim) {
