    stack.add(v);
    onStack.add(v);

    for (var neighbour in graph[v] ?? []) {
      if (disc[neighbour] == -1) {
        dfsFirst(neighbour);
        low[v] = low[v] < low[neighbour] ? low[v] : low[neighbour];
      } else if (onStack.contains(neighbour)) {
        low[v] = low[v] < disc[neighbour] ? low[v] : disc[neighbour];
      }
    }
  }

  void dfsSecond(int v) {
    if (low[v] != -1) return;
    onStack.remove(v);

    for (var neighbour in graph[v] ?? []) {
      if (onStack.contains(neighbour)) {
        onStack.remove(neighbour);
      }
    }
    stack.add(v);
  }

  for (var v in graph.keys) {
    if (disc[v] == -1) {
      dfsFirst(v);
    }
  }

  while (stack.isNotEmpty) {
    var v = stack.removeLast();
    if (!onStack.contains(v)) {
      dfsSecond(v);
    }
  }

  print('Strongly Connected Components:');
  for (var component in stack) {
    print(component);
  }
}

