double fn0(List<int> heights, int windowSize) {
  if (heights.isEmpty || windowSize <= 0) return 0.0;

  int sum = 0;
  for (int i = 0; i < windowSize; i++) {
    sum += heights[i];
  }
  double avg = sum / windowSize.toDouble();

  double maxSum = avg;
  for (int i = windowSize; i < heights.length; i++) {
    sum += heights[i] - heights[i - windowSize];
    double newAvg = sum / windowSize.toDouble();
    if (newAvg > maxSum) {
      maxSum = newAvg;
    }
  }

  return maxSum / 2.0;
}

