  int randBetween(int a, int b) {
    return a + random.nextInt(b - a + 1);
  }

  bool millerRabin(int n, int d) {
    if (n <= 1) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0) return false;

    final int e = n - 1;
    int s = 0;
    int t = e;

    while (t > 0) {
      if (t & 1 == 1) s++;
      t >>= 1;
    }

    if (s != d) return false;

    bool isPrime = true;
    for (int i = 0; i < d; i++) {
      int a = randBetween(1, n - 1);
      int b = randBetween(1, n - 1);

      int x = a;
      int y = b;
      int lastX = a;
      int lastY = b;

      while (y != 0) {
        int temp = y;
        y = x % y;
        x = temp;

        int temp2 = lastX;
        lastX = lastY;
        lastY = temp2;
      }

      if (x != 1) {
        isPrime = false;
        break;
      }
    }

    return isPrime;
  }

  print("Miller-Rabin Primality Test");

  print("\nTesting known small primes:");
