import 'dart:convert';
class Node {
  int key;
  Node? next;
  Node(this.key, [this.next]);
}

class HashTable {
  final int capacity;
  List<Node?> table1 = [];
  List<Node?> table2 = [];

  HashTable(this.capacity) {
    for (var i = 0; i < capacity; i++) {
      table1.add(null);
      table2.add(null);
    }
  }

  int hash1(int key) {
    int hash = key % capacity;
    if (hash < 0) {
      hash += capacity;
    }
    return hash;
  }

  int hash2(int key) {
    int hash = (key % capacity + capacity) % capacity;
    return hash;
  }

  bool insert(int key) {
    int h1 = hash1(key);
    int h2 = hash2(key);
    Node? node1 = table1[h1];
    Node? node2 = table2[h2];

    bool found1 = node1 != null && node1.key == key;
    bool found2 = node2 != null && node2.key == key;

    if (found1 || found2) return false;

    int next1 = node1?.next?.hashCode ?? -1;
    int next2 = node2?.next?.hashCode ?? -1;

    if (next1 == h1 || next2 == h2) {
      return false; 
    }

    table1[h1] = Node(key, node1);
    table2[h2] = Node(key, node2);
    return true;
  }

  bool contains(int key) {
    int h1 = hash1(key);
    int h2 = hash2(key);
    return table1[h1] != null && table1[h1].key == key ||
           table2[h2] != null && table2[h2].key == key;
  }

  bool delete(int key) {
    int h1 = hash1(key);
    int h2 = hash2(key);

    Node? node1 = table1[h1];
    Node? node2 = table2[h2];

    bool found1 = node1 != null && node1.key == key;
    bool found2 = node2 != null && node2.key == key;

    if (!found1 && !found2) return false;

    table1[h1] = Node.next;
    table2[h2] = Node.next;
    return true;
  }
}

