  List<List<int>> population = List.generate(
    populationSize,
    (_) => List<int>.generate(32, (_) => random.nextInt(2)),
  );

  int fitness(List<int> individual) {
    int fitness = 0;
    for (int i = 0; i < individual.length; i++) {
      if (individual[i] == 1) {
        fitness++;
      }
    }
    return fitness;
  }

  List<int> selectParent() {
    final int tournamentSize = 3;
    List<List<int>> tournament = List<List<int>>.generate(
      tournamentSize,
      (_) => population[random.nextInt(populationSize)],
    );
    tournament.sort((a, b) {
      final fitA = fitness(a);
      final fitB = fitness(b);
      if (fitA != fitB) return fitB.compareTo(fitA);
      return a.length.compareTo(b.length);
    });
    return tournament.first;
  }

  List<int> crossover(List<int> parent1, List<int> parent2) {
    if (random.nextDouble() > crossoverRate) {
      return [...parent1, ...parent2];
    }
    final int point = random.nextInt(32);
    final List<int> child1 = List<int>.from(parent1.sublist(0, point));
    final List<int> child2 = List<int>.from(parent2.sublist(point));
    child1.addAll(child2);
    return child1;
  }

  List<int> mutate(List<int> individual) {
    final List<int> mutated = List<int>.generate(
      individual.length,
      (_) => individual[random.nextInt(individual.length)] == 1
          ? 0
          : 1,
    );
    final int fitness = fitness(mutated);
    if (fitness > fitness(individual)) {
      return mutated;
    }
    return individual;
  }

  int bestIndividualFitness = 0;
  List<int> bestIndividual = [];

  for (int generation = 1; generation <= generations; generation++) {

    List<List<int>> newPopulation = [];

    while (newPopulation.length < populationSize) {

      final List<int> parent1 = selectParent();
      final List<int> parent2 = selectParent();

      final List<int> offspring = crossover(parent1, parent2);

      offspring = mutate(offspring);

      newPopulation.add(offspring);
    }
    population = newPopulation;

    final int currentBest = population.map(fitness).reduce((a, b) => a > b ? a : b);
    if (currentBest > bestIndividualFitness) {
      bestIndividualFitness = currentBest;
      bestIndividual = population.first;
    }

    print(
      'Generation $generation: Best fitness = $currentBest',
    );
  }

  print('Final best individual: $bestIndividual');
}

