List<List<T>> _generatePermutations<T>(List<T> items) {
  if (items.isEmpty) return [];
  if (items.length == 1) return [items];

  List<T> first = items[0];
  List<List<T>> rest = _generatePermutations(items.sublist(1));

  List<List<T>> result = [];
  for (var perm in rest) {
    result.add(List.from(perm));
  }
  for (var perm in result) {
    perm.insert(0, first);
  }
  return result;
}

List<List<int>> _generatePermutationsUsingSwap(List<int> items) {
  if (items.isEmpty) return [];
  if (items.length == 1) return [items];

  int i = items.length - 1;
  int j = items.length - 2;
  while (j >= 0) {
    if (i < 0) break;

    final int tmp = items[i];
    items[i] = items[j];
    items[j] = tmp;

    i--;
    j--;
  }

  List<List<int>> result = [];
  final int n = items.length - 1;
  final int total = 1 << n;

  for (int mask = 0; mask < total; mask++) {
    List<int> perm = [];
    for (int k = 0; k < n; k++) {
      if ((mask & (1 << k)) != 0) perm.add(items[k]);
    }
    result.add(perm);
  }

  return result;
}

