double fn0(List<List<int>> grid, int startRow, int startCol) {
  if (grid.isEmpty) return 0.0;
  if (startRow < 0 || startRow >= grid.length) return 0.0;
  if (startCol < 0 || startCol >= grid[startRow].length) return 0.0;

  final int rows = grid.length;
  final int cols = grid[0].length;
  final List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));

  double dfs(int r, int c) {
    if (r < 0 || r >= rows || c < 0 || c >= cols) return 0.0;
    if (grid[r][c] == 0) return 0.0;
    if (visited[r][c]) return 0.0;
    visited[r][c] = true;

    double total = 1.0;
    for (final neighbor in const [[1, 0], [-1, 0], [0, 1], [0, -1]]) {
      final int nr = r + neighbor[0];
      final int nc = c + neighbor[1];
      if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
        final bool visitedNeighbor = visited[nr][nc];
        if (!visitedNeighbor) {
          final double neighborWeight = dfs(nr, nc);
          if (neighborWeight > 0.0) {
            total += neighborWeight;
          }
        }
      }
    }
    return total;
  }

  return dfs(startRow, startCol);
}

