      if (chromosome[i] == 1) {
        fit += i + 1;
      }
    }
    return fit;
  }

  List<int> selectParent() {
    final tournamentSize = 3;
    final tournament = List<int>.generate(
      tournamentSize,
      (_) => generateRandomChromosome(),
    );
    tournament.sort((a, b) => fitness(b).compareTo(fitness(a)));
    return tournament.first;
  }

  List<int> crossover(List<int> parent1, List<int> parent2) {
    final point = random.nextInt(chromosomeLength);
    final child = <int>[];
    for (int i = 0; i < point; i++) {
      child.add(parent1[i]);
    }
    for (int i = point; i < parent2.length; i++) {
      child.add(parent2[i]);
    }
    return child;
  }

  List<int> mutate(List<int> chromosome) {
    for (int i = 0; i < chromosome.length; i++) {
      if (random.nextDouble() < mutationRate) {
        chromosome[i] = 1 - chromosome[i];
      }
    }
    return chromosome;
  }

  List<int> best = generateRandomChromosome();
  int bestFit = fitness(best);

  for (int gen = 0; gen < generations; gen++) {

    final current = <int>[];

    for (int i = 0; i < populationSize; i++) {
      final parent1 = selectParent();
      final parent2 = selectParent();

      final child = random.nextDouble() < crossoverRate
          ? crossover(parent1, parent2)
          : List<int>.from(parent1);

      child.sort();
      current.add(child);
    }

    current.sort((a, b) => fitness(b).compareTo(fitness(a)));

    best = current.first;
    bestFit = fitness(best);

    if (bestFit == chromosomeLength) {
      print('Generation $gen | Best fitness: $bestFit | Chromosome: $best');
      break;
    }

    current = mutate(current);
    current.sort((a, b) => fitness(b).compareTo(fitness(a)));

    best = current.first;
    bestFit = fitness(best);

    print('Generation $gen | Best fitness: $bestFit | Chromosome: $best');
  }
}

