  final cities = [
    [0, 0],
    [1, 4],
    [2, 3],
    [3, 2],
    [4, 1],
  ];

  final int n = cities.length;

  double distance(List<int> a, List<int> b) {
    double sum = 0.0;
    for (var i = 0; i < a.length - 1; i++) {
      final int da = a[i];
      final int db = a[i + 1];
      sum += pow(da - db, 2).toDouble();
    }
    return sqrt(sum);
  }

  double totalDistance(List<int> route) {
    double total = 0.0;
    for (var i = 0; i < route.length - 1; i++) {
      total += distance(route[i], route[i + 1]);
    }
    return total;
  }

  List<int> generatePermutations(List<int> list) {
    if (list.isEmpty) return [];
    List<int> result = [];
    int n = list.length;
    while (n > 0) {
      int k = n ~/ 2;
      result.add(list[k]);
      List<int> remaining = list.sublist(0, k) + list.sublist(k + 1);
      result.addAll(generatePermutations(remaining));
      n -= k;
    }
    return result;
  }

  void printRoute(List<int> route) {
    print('  City ${String.fromCharCode(65 + route[0])},');
    for (var i = 1; i < route.length; i++) {
      print('  City ${String.fromCharCode(65 + route[i])},');
    }
  }

  List<int>? bestRoute;
  double? bestDistance = double.infinity;

  for (var permutation in generatePermutations(List.generate(n, (i) => i))) {
    List<int> route = [];
    for (var i = 0; i < n; i++) {
      route.add(permutation[i]);
    }
    double dist = totalDistance(route);
    if (dist < bestDistance ||
        (dist == bestDistance &&
            (bestRoute == null || route.length < bestRoute!.length))) {
      bestRoute = route;
      bestDistance = dist;
    }
  }

  if (bestRoute != null) {
    print('Traveling Salesman Problem - Brute Force Solution');
    print('=' * 50);
    print('Number of cities: $n');
    print('Cities coordinates:');
    for (var city in cities) {
      print('  ${String.fromCharCode(65 + city[0])}, ${city[1]}');
    }
    print('\nTotal permutations checked: ${generatePermutations(List.generate(n, (i) => i)).length}');
    print('\nBest route found:');
    printRoute(bestRoute!);
    print('\nTotal distance: ${bestDistance.toStringAsFixed(2)}');
  } else {
    print('No route found!');
  }
}

