  if (entries.isEmpty) return <int>[];

  List<List<int>> bucketized = [];
  for (var e in entries) {
    int idx = e[0] % bucketCount;
    if (idx < 0) idx += bucketCount;
    bucketized.add([e[1], idx]);
  }

  bucketized.sort((a, b) {
    int cmp = a[1].compareTo(b[1]);
