  print('\nTrained weights: $weight1, $weight2, $bias');

  print('\nTesting perceptron on AND logic:');
  for (var i = 0; i < X.length; i++) {
    List<double> x = X[i];
    int y = y[i];
    bool p = predict(x);
    print('Input: $x -> Predicted: $p, Target: $y');
  }
}

