class FenwickTree {
  late List<int> tree;
  int n;

  FenwickTree(int n) {
    this.n = n;
    tree = List<int>.filled(n + 1, 0);
  }

  void update(int index, int val) {
    while (index <= n) {
      tree[index] += val;
      index += index & -index;
    }
  }

  int query(int index) {
    int sum = 0;
    while (index > 0) {
      sum += tree[index];
      index -= index & -index;
    }
    return sum;
  }
}

