List<String> fn0(List<String> shelfCodes, List<int> weights, int capacity, int threshold) {
  List<String> result = [];
  int n = shelfCodes.length;

  if (n == 0 || capacity <= 0) {
    return result;
  }

  if (capacity <= threshold) {
    for (int i = 0; i < n; i++) {
      result.add(shelfCodes[i]);
    }
    return result;
  }

  List<List<int>> dp = List.generate(n + 1, (_) => List<int>.filled(capacity + 1, 0));

  for (int i = 1; i <= n; i++) {
    for (int j = 0; j <= capacity; j++) {
      if (weights[i - 1] <= j) {
        dp[i][j] = dp[i - 1][j];
      } else {
        int take = (i > 1 ? dp[i - 2][j - weights[i - 1]] : 0) + weights[i - 1];
        int skip = dp[i - 1][j];
        dp[i][j] = take > skip ? take : skip;
      }
    }
  }

  int best = dp[n][capacity];

  int idx = n;
  int j = capacity;
  while (idx > 0 && j > 0) {
    if (dp[idx - 1][j] == dp[idx][j - 1]) {
      idx--;
    } else {
      j--;
      idx--;
    }
  }

  if (best > threshold) {
    result.add(shelfCodes[idx]);
  }

  return result;
}

