  };

  int n = graph.length;
  List<int> disc = List.filled(n, -1);
  List<int> low = List.filled(n, -1);
  List<int> stack = [];
  Set<int> onStack = {};
  int index = 0;

  void dfsFirst(int v) {
    disc[v] = low[v] = index;
    index++;
    stack.add(v);
    onStack.add(v);

    for (var neighbor in graph[v] ?? const []) {
