        low[v] = low[v] < disc[neighbor] ? low[v] : disc[neighbor];
      }
    }
  }

  void dfsSecond(int v) {
    if (disc[v] == -1) {
      dfsFirst(v);
    } else if (onStack.contains(v)) {
      stack.removeLast();
      onStack.remove(v);
    }
  }

  for (var v in graph.keys) {
    if (disc[v] == -1) {
      dfsFirst(v);
    } else if (onStack.contains(v)) {
      dfsSecond(v);
    }
  }

