enum FormValidationResult {
  valid,
  invalid,
  invalidEmail,
  invalidPassword,
  invalidUsername,
  invalidPhone,
  invalidAge,
  invalidZipCode,
}

class FormValidator {
  final Map<String, FormFieldValidator> validators;

  FormValidator(this.validators);

  bool validate(Map<String, String> data) {
    for (var field in data.keys) {
      var validator = validators[field];
      if (validator == null) continue;
      var issue = validator.validate(data[field]!);
      if (issue != null) {
        return issue;
      }
    }
    return FormValidationResult.valid;
  }
}

class FormFieldValidator {
  final String field;
  final List<String> issues;

  FormFieldValidator(this.field);

  String? validate(String value) {
    if (value == null || value.isEmpty) {
      return field;
    }
    for (var issue in issues) {
      if (issue.isEmpty) continue;
      if (value.contains(issue)) {
        return issue;
      }
    }
    return null;
  }
}

