/// Abstract class acting as an interface for all priority queues.
abstract class PriorityQueue<T extends Comparable<T>> {
  void insert(T value);
  T? remove();
  T? peek();
}

/// A simple implementation of PriorityQueue using a List<T> where T implements Comparable<T>.
class MinHeap<T extends Comparable<T>> implements PriorityQueue<T> {
  List<T> heap;
  int count;
  int? _peek;

  MinHeap(this.heap) {
    this.count = heap.length;
  }

  void insert(T value) {
    heap.add(value);
    count++;
    int index = count - 1;
    while (index > 0) {
      int parent = (index - 1) ~/ 2;
      if (heap[parent].compareTo(value) >= 0) {
        heap[index] = heap[parent];
        index = parent;
      } else {
        break;
      }
    }
    heap[index] = value;
  }

  T? remove() {
    if (count < 2) return null;

    T? root = heap[0];
    heap[0] = heap[count - 1];
    count--;
    int left = 2 * 1 + 1;
    int right = 2 * 1 + 2;
    int index = 0;

    if (left < count && heap[left].compareTo(heap[right]) < 0) {
      index = left;
    } else if (right < count && heap[right].compareTo(heap[left]) < 0) {
      index = right;
    }

    if (index < count) {
      heap[index] = heap[count - 1];
      count--;
      _heapifyDown(index);
    }

    return root;
  }

  T? peek() {
    return _peek ??= heap[0];
  }

  void _heapifyDown(int index) {
    int smaller = index * 2 + 1;
    int left = smaller;
    int right = smaller + 1;
    int smallest = index;

    if (left < count && heap[left].compareTo(heap[right]) < 0) {
      left = smaller;
    } else if (right < count && heap[right].compareTo(heap[left]) < 0) {
      right = smaller;
    }

    if (smallest != index) {
      heap[index] = heap[smallest];
      index = smallest;
      _heapifyDown(index);
    }
  }
}

