  var result = <T>[];
  for (var item in list) {
    if (item is List<T>) {
      result.addAll(item);
    } else {
      result.add(item);
    }
  }
  return result;
}

Set<T> setSpread<T>(Set<T> set) {
  var result = <T>{};
  for (var item in set) {
    if (item is Set<T>) {
      result.addAll(item);
    } else {
      result.add(item);
    }
  }
  return result;
}

List<MapEntry<T, U>> mapEntriesSpread<T, U>(Map<T, U> map) {
  var result = <MapEntry<T, U>>[];
  for (var entry in map.entries) {
    if (entry.value is Map<T, U>) {
      result.addAll(entry.value.entries);
    } else {
      result.add(MapEntry(entry.key, entry.value));
    }
  }
  return result;
}

