void fn0() {

  List<List<double>> points = [
    [2, 3],
    [5, 4],
    [9, 6],
    [4, 7],
    [8, 1],
    [7, 2],
    [3, 5],
    [2, 5],
    [10, 11],
  ];

  int k = 2; 

  final random = Random(0);
  List<int> clusterAssignments = List.filled(points.length, -1);

  List<double> centroids = [];

  for (int i = 0; i < k; i++) {
    final int index = random.nextInt(points.length);
    if (!clusterAssignments.contains(index)) {
      clusterAssignments[index] = i;
      centroids.add(points[index]);
    }
  }

  List<int> clusterCounts = List.filled(k, 0);

  for (int i = 0; i < points.length; i++) {
    if (clusterAssignments[i] >= 0) {
      clusterCounts[clusterAssignments[i]]++;
    }
  }

  double calculateDistance(List<double> a, List<double> b) {
    double sum = 0.0;
    for (int i = 0; i < a.length; i++) {
      final diff = a[i] - b[i];
      sum += diff * diff;
    }
    return sqrt(sum);
  }

  while (true) {
    bool changed = false;

    for (int i = 0; i < points.length; i++) {
      if (clusterAssignments[i] >= 0) {
        double minDist = double.infinity;
        int bestCluster = -1;

        for (int j = 0; j < k; j++) {
          if (clusterAssignments[i] == j) continue;

          double dist = calculateDistance(points[i], centroids[j]);
          if (dist < minDist) {
            minDist = dist;
            bestCluster = j;
          }
        }

        if (bestCluster != -1) {
          clusterAssignments[i] = bestCluster;
          clusterCounts[bestCluster]++;
          clusterCounts[clusterAssignments[i]]--;
          changed = true;
        }
      }
    }

    if (!changed) break;
  }

  for (int i = 0; i < k; i++) {
    print('Cluster $i:');
