  if (targets.isEmpty) return false;
  if (k > total) return false;

  for (int i = 0; i <= total - k; i++) {
    int currentSum = 0;
    for (int j = i; j < i + k; j++) {
      currentSum += nums[j];
    }

    int targetSum = 0;
    for (int j = 0; j < k; j++) {
      targetSum += targets[j];
