void fn0(List<String> args) {



  final int n = args.isNotEmpty ? int.tryParse(args[0]) ?? 8 : 8;
  if (n <= 0) {
    print('Board size must be positive.');
    return;
  }

  const String queen = 'Q';
  const String empty = '.';

  final List<List<String>> board = List.generate(
    n,
    (_) => List.filled(n, empty),
  );

  int solutions = 0;

  bool isSafe(int row, int col, List<List<String>> board) {
    for (int i = 0; i < row; i++) {
      final int colI = board[i][col];
      if (colI == queen) return false;
    }
    final int rowI = board[row][col];
    if (rowI == queen) return false;
    final int colLeft = col - 1;
    final int colRight = col + 1;
    for (int c = colLeft; c <= colRight; c++) {
      final int rowC = board[row][c];
      if (rowC == queen) return false;
    }
    return true;
  }

  void solve(int row, List<List<String>> board) {
    if (row == n) {
      solutions++;
      print('Solution #$solutions');
      for (final row in board) {
        print(row.join(' '));
      }
      print('');
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(row, col, board)) {
        board[row][col] = queen;
        solve(row + 1, board);
        board[row][col] = empty;
      }
    }
  }

  solve(0, board);
  print('Total solutions for N=$n: $solutions');
}

