void fn0(List<String> args) {

  if (args.length != 1) {
    print('Usage: dart fn0 [N]');
    print('N is the size of the chessboard (a positive integer)');
    return;
  }

  final n = int.tryParse(args[0]);
  if (n == null || n < 0) {
    print('Board size must be positive.');
    return;
  }

  const List<String> queens = List<String>.generate(n, (i) => 'Q${i + 1}');

  bool isSafe(List<String> queens, int row, int col) {

    for (int i = 0; i < row; i++) {
      final c = queens[i].codeUnitAt(col);
      if (c == 104 || c == 109) {
        return false;
      }
    }
    return true;
  }

  int totalSolutions = 0;
  void solve(List<String> queens, int row) {

    if (row == n) {

      totalSolutions++;
      print('Solution #$totalSolutions');
      for (int i = 0; i < n; i++) {
        final row = queens.map((q) => q).toList();
        print(row.join(' '));
      }
      print('');
      return;
    }

    for (int col = 0; col < n; col++) {
      if (isSafe(queens, row, col)) {
        queens[row] = queens[row].split('')..insert(col, 'Q');
        solve(queens, row + 1);
        queens[row] = queens[row].split('')..removeLast();
      }
    }
  }

  solve(queens, 0);
  print('Total solutions for N=$n: $totalSolutions');
}

