  if (n <= 0) {
    print('Board size must be positive.');
    return;
  }

  final List<List<String>> board = List.generate(n, (_) => List<String>.filled(n, '.'));

  int totalSolutions = 0;
  void solve(int row) {
    if (row == n) {
      totalSolutions++;
      print('Solution #$totalSolutions');
      for (final line in board) {
        print(line.join(' '));
      }
      print('');
      return;
    }
    for (int col = 0; col < n; col++) {
      if (board[row][col] == 'Q') continue; 
      if (col > 0 && board[row][col - 1] == 'Q') continue; 
      if (row > 0 && (board[row - 1][col] == 'Q' || board[row - 1][col - 1] == 'Q')) continue; 
      board[row][col] = 'Q';
      solve(row + 1);
      board[row][col] = '.';
    }
  }

  print('Total solutions for N=$n: $totalSolutions');

  solve(0);
}

