int totalSections = 0;

void parse(String input) {
  List<String> tokens = input.split(' ');
  List<String> stack = [];

  for (String token in tokens) {
    if (token == '[') {
      stack.add(token);
    } else if (token == ']') {
      if (stack.isEmpty) return;
      stack.removeLast();
      totalSections++;
    } else if (token.length > 1) {
      return;
    } else {
      stack.add(token);
    }

    if (stack.isNotEmpty) {
      if (stack.last == '[') {
        maxDepth++;
      } else if (stack.last == ']') {
        maxDepth--;
      }
    }
  }

  if (stack.isNotEmpty) return;
  validSections.add(input);
}

