  final List<int> next = List<int>.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    final String c = input[i];
    if (c == 'd') {
      prev[i + 1] = i + 1;
      next[i + 1] = 0;
    } else if (c == 'i') {
      prev[i + 1] = 0;
      next[i + 1] = i + 1;
