void fn0() {

  List<List<String>> board = [
    ['O', 'X', 'O'],
    ['X', 'O', 'X'],
    ['O', 'X', 'O'],
  ];

  int bestMove = -1; 
  int bestScore = -1000000000; 

  void evaluate(List<List<String>> board, int player) {
    if (board.isEmpty) {
      return 0; 
    }

    int count = 0;
    for (final row in board) {
      for (final cell in row) {
        if (cell == 'X' || cell == 'O') {
          count++;
        }
      }
    }
    if (count == 9) {
      return player == 1 ? 1 : -1; 
    }

    int winning = 0;
    for (final row in board) {
      if (row.contains('X') && !row.contains('O')) {
        winning = 1;
        break;
      }
      if (row.contains('O') && !row.contains('X')) {
        winning = -1;
        break;
      }
    }
    return winning;
  }

  void search(int depth, List<List<String>> board, int player) {

    int score = evaluate(board, player);
    if (score != -1) {
      return score;
    }

    List<List<String>> moves = [];
    for (int i = 0; i < board.length; i++) {
      for (int j = 0; j < board[i].length; j++) {
        if (board[i][j] == ' ') {
          moves.add(List<String>.from(board));
          moves[moves.length - 1][j] = player == 1 ? 'X' : 'O';
        }
      }
    }

    int alphaBeta = -1000000000;
    for (final move in moves) {
      search(depth + 1, move, player * -1);

      int beta = alphaBeta;
      if (player == 1) {
        alphaBeta = alphaBeta > beta ? alphaBeta : beta;
      } else {
        alphaBeta = alphaBeta > beta ? alphaBeta : beta;
      }
      if (alphaBeta > bestScore) {
        bestScore = alphaBeta;
        bestMove = depth;
      }
    }
    return alphaBeta;
  }

  search(0, board, 1);

  if (bestMove != -1) {
    print('Sample Board:');
    for (final row in board) {
      print(row.join(' '));
    }
    print('\nBest move for X is position: $bestMove (0-8 indexing)');
  } else {
    print('No valid move found for X');
  }
}

