class ListNode {
  final int value;
  ListNode? next;

  ListNode(this.value, {this.next});
}

class HashTable {
  final int capacity;
  final List<ListNode?> tables;

  HashTable(this.capacity) : tables = List.filled(capacity, null);

  void _rehash(int key) {
    int bucket = key % capacity;
    if (tables[bucket] == null) {
      tables[bucket] = ListNode(key);
    } else {
      ListNode? current = tables[bucket];
      while (current!.next != null) {
        current = current!.next!;
      }
      current!.next = ListNode(key);
    }
  }

  void _delete(int key) {
    int bucket = key % capacity;
    if (tables[bucket] == null) return;

    ListNode? current = tables[bucket];
    ListNode? previous;
    while (current != null) {
      if (current.value == key) {
        if (previous == null) {
          tables[bucket] = current!.next!;
        } else {
          previous!.next = current!.next!;
        }
        break;
      }
      previous = current;
      current = current!.next!;
    }
  }

  void insert(int key) {
    if (key < 0) return;

    int bucket = key % capacity;
    if (tables[bucket] == null) {
      tables[bucket] = ListNode(key);
    } else {
      ListNode? current = tables[bucket];
      while (current!.next != null) {
        current = current!.next!;
      }
      current!.next = ListNode(key);
    }

    _rehash(key);
  }

  bool lookup(int key) {
    if (key < 0) return false;

    int bucket = key % capacity;
    if (tables[bucket] == null) return false;

    ListNode? current = tables[bucket];
    while (current != null) {
      if (current.value == key) return true;
      current = current!.next;
    }
    return false;
  }

  void delete(int key) {
    if (key < 0) return;

    int bucket = key % capacity;
    _delete(key);

    _rehash(key);
  }
}

