  final List<List<int>> tables;

  HashTable(this.capacity) {
    tables = List.generate(capacity, (_) => List.filled(capacity, 0));
  }

  int hashFunction(int key) {
    int hash = 0;
    for (int i = 0; i < key.length; i++) {
      hash = (hash + key.codeUnitAt(i)) % capacity;
    }
    return hash;
  }

  bool insert(int key) {
    int h = hashFunction(key);
    int count = 0;
    while (count < capacity) {
      if (tables[h][count] == 0) {
        tables[h][count] = key;
        return true;
      }
      count++;
    }
    return false;
  }

  bool lookup(int key) {
    int h = hashFunction(key);
    int count = 0;
    while (count < capacity) {
      if (tables[h][count] == key) {
        return true;
      }
      count++;
    }
    return false;
  }

  bool delete(int key) {
    int h = hashFunction(key);
    int count = 0;
    while (count < capacity) {
      if (tables[h][count] == key) {
        tables[h][count] = 0;
        return true;
      }
      count++;
    }
    return false;
  }
}

