        current.right = node;
      } else {
        insertHelper(current.right, node);
      }
    } else {
      current.y = node.y;
    }
  }

  void printTree(KDNode? node, [int depth = 0]) {
    if (node == null) return;
    print('KDNode(${node.x}, ${node.y})');
    print('  ' * depth + '└─> ${node.left}');
    print('  ' * depth + '├─> ${node.right}');
