class KDTree {
  KDNode? root;

  KDTree(List<List<double>> points) {
    build(points, 0);
  }

  void build(List<List<double>> points, int depth) {
    if (points.isEmpty) return;

    int k = points[0].length;
    int axis = depth % k;

    points.sort((a, b) {
      double da = a[axis] as double;
      double db = b[axis] as double;
      return da.compareTo(db);
    });

    int median = points.length ~/ 2;
    var node = KDNode(points[median]);
    root = node;

    List<List<double>> left = [];
    List<List<double>> right = [];
    for (var point in points) {
      if (point[axis] <= node.point[axis]) {
        left.add(point);
      } else {
        right.add(point);
      }
    }

    node.left = KDNode(left);
    node.right = KDNode(right);

    build(left, depth + 1);
    build(right, depth + 1);
  }

  void printTree(KDNode? node, int depth) {
    if (node == null) return;
    print('KDNode(${node.point.join(', ')})');
    printTree(node.left, depth + 1);
    printTree(node.right, depth + 1);
  }

  void printTree() {
    print('Constructed k-d tree:');
    printTree(root, 0);
  }
}

