int _findIndex(List<List<int>> items, List<int> target) {
  int lo = 0;
  int hi = items.length - 1;
  int result = -1;

  while (lo <= hi) {
    int mid = lo + (hi - lo) ~/ 2;
    List<int> a = items[mid];
    List<int> b = target;

    int cmp = a[0].compareTo(b[0]);
    if (cmp != 0) {
      if (cmp < 0) {
        hi = mid - 1;
      } else {
        lo = mid + 1;
      }
    } else {
      int distA = (a[0] - b[0]).abs() + (a[1] - b[1]).abs();
      int distB = (items[mid][0] - b[0]).abs() + (items[mid][1] - b[1]).abs();
      if (distA < distB) {
        result = mid;
        lo = mid + 1;
      } else if (distA > distB) {
        hi = mid - 1;
      } else {
        result = mid;
      }
    }
  }

  return result;
}

