void fn0() {

  Iterable<int> fibonacci(int n) sync* {
    int a = 0, b = 1;
    for (int i = 0; i < n; i++) {
      yield a; 
      int next = a + b;
      a = b;
      b = next;
    }
  }

  Iterable<int> naturals(int n) sync* {
    for (int i = 1; i <= n; i++) {
      yield i;
    }
  }

  Iterable<int> squaresUpTo(int n) sync* {
    for (var value in naturals(n)) {
      yield value * value;
    }
  }

  print('Fibonacci numbers ≤ 100:');
  for (var value in fibonacci(100)) {
    print(value);
  }

  print('\nSquares of the first 10 natural numbers:');
  for (var value in squaresUpTo(10)) {
    print(value);
  }
}

