void fn0() {

  List<List<int>> graph = [
    [0, 1, 0, 0], 
    [1, 0, 1, 0], 
    [0, 1, 0, 1], 
    [0, 0, 1, 0], 
  ];

  int n = graph.length;

  List<bool> visited = List<bool>.filled(n, false);

  List<int> path = List<int>.filled(n, -1);

  bool hasHamiltonianPath() {
    for (int i = 0; i < n; i++) {
      if (visited[i] == false) {
        return false;
      }
    }
    return true;
  }

  void generateHamiltonianPath(int v, int count) {
    if (count == n) {
      if (hasHamiltonianPath()) {
        print('Hamiltonian Path exists: ${path.join(" -> ")}');
      }
      return;
    }
    for (int u = 0; u < n; u++) {
      if (graph[v][u] == 1 && visited[u] == false) {
        visited[u] = true;
        path[count] = u;
        generateHamiltonianPath(u, count + 1);
        path[count] = -1;
        visited[u] = false;
      }
    }
  }

  generateHamiltonianPath(0, 0);
  print('No Hamiltonian Path exists');
}

