  ];

  int n = graph.length;

  bool hasHamiltonianPath(List<int> path) {
    for (int i = 1; i < path.length; i++) {
      if (graph[path[i - 1]][path[i]] == 0) {
        return false;
      }
    }
    return true;
  }

  List<int> findHamiltonianPathUtil(List<int> path, int pos) {
    if (pos == n) {
      return path;
    }

    for (int v in graph[path[pos - 1]]) {
      path[pos] = v;
      if (findHamiltonianPathUtil(path, pos + 1)) {
        return path;
      }
    }
    return [];
  }

  bool hamiltonianPathUtil(List<int> path) {
    return findHamiltonianPathUtil(path, 1);
  }

  List<int> hamiltonianPath() {
    List<int> path = [];
    for (int v in graph[0]) {
      path.add(v);
    }
    return hamiltonianPathUtil(path);
  }

  if (hamiltonianPath() != []) {
    print('Hamiltonian Path exists: ${hamiltonianPath().join(" -> ")}');
  } else {
    print('No Hamiltonian Path exists');
  }
}

