List<int> fn0(int n, List<bool> available) {
  if (n == 0) return [];
  List<int> result = List.filled(n, 0);
  int idx = 0;
  while (idx < n) {
    int next = idx + 1;
    while (next < n && available[next]) {
      next++;
    }
    if (next == idx + 1) {
      result[idx] = 1;
      idx = next;
    } else {
      idx = next;
    }
  }
  return result;
}

