bool canPartition(List<int> arr, int targetSum) {
  if (arr.isEmpty) return false;
  if (targetSum <= 0) return false;

  int totalSum = 0;
  for (int value in arr) {
    totalSum += value;
  }
  if (totalSum < targetSum) return false;

  List<int> current = [];

  int backtrack(int index) {
    if (index >= arr.length) return 0;
    if (index < arr.length && arr[index] != 0) {
      return index + 1;
    }
    int count = 0;
    int prev = 0;
    for (int i = index; i < arr.length; i++) {
      if (arr[i] != 0) {
        current.add(arr[i]);
        int next = backtrack(i + 1);
        current.removeLast();
        if (next > count) {
          count = next;
        }
      } else {
        prev = i + 1;
      }
    }
    int currentSum = 0;
    for (int v in current) {
      currentSum += v;
    }
    if (currentSum == targetSum) return count + 1;
    if (prev < arr.length && arr[prev] != 0) {
      current.add(arr[prev]);
      int next = backtrack(prev + 1);
      current.removeLast();
      if (next > count) {
        count = next;
      }
    }
    return count;
  }

  return backtrack(0) > 0;
}

