void fn0() {



  final nodes = <String>['A', 'B', 'C', 'D'];
  final n = nodes.length;
  final damping = 0.85; 

  final edges = <List<String>>[
    ['A', 'B'],
    ['A', 'C'],
    ['B', 'C'],
    ['B', 'D'],
    ['C', 'A'],
    ['C', 'D'],
    ['D', 'C'],
    ['D', 'B'],
  ];

  final pageRank = <String, double>{};
  for (final v in nodes) {
    pageRank[v] = 1.0 / n;
  }

  const double EPSILON = 1.0e-4;
  var convergence = false;

  while (!convergence) {
    convergence = true;

    final newPageRank = <String, double>{};
    for (final u in nodes) {
