    }

    for (final u in nodes) {
      final diff = (newPageRank[u]! - pageRank[u]!).abs();
      if (diff > EPSILON) {
        convergence = false;
      }
    }

    pageRank = newPageRank;
  }

  print('Final PageRank values:');
  for (final u in nodes) {
    print('$u: ${pageRank[u]}');
  }
