  Set<int> intervals = {};
  if (cycleMinutes <= 0 || redSeconds <= 0 || greenSeconds <= 0 || blueSeconds <= 0) {
    return intervals;
  }
  int interval = cycleMinutes * 60;
  for (int i = 0; i < red.length; i++) {
