    final newList = <E>[];
    for (var i = 0; i < list.length; i++) {
      if (i != index) newList.add(list[i]);
    }
    return MyList<E>(newList);
  }

  MyList<E> operator ~(E e) {
    if (list.contains(e)) {
      return MyList<E>(list - e);
    } else {
      return MyList<E>(list + e);
    }
  }

  void print() {
