/// Abstract class acting as an interface for all binary search trees.
abstract class BinarySearchTree {

  /// Abstract method to insert a value into the BST.
  void insert(int value);

  /// Abstract method to search for a value in the BST.
  bool search(int value);

  /// Abstract method to delete a value from the BST.
  void delete(int value);
}

/// Class implementing the BinarySearchTree interface.
class BinarySearchTreeImpl extends BinarySearchTree {
  int root;

  BinarySearchTreeImpl(this.root);

  @override
  void insert(int value) {
    root = _insert(value, root);
  }

  int _insert(int value, BinarySearchTreeImpl? current) {
    if (current == null) {
      return BinarySearchTreeImpl(value);
    }

    if (value < current.value) {
      current.left = _insert(value, current.left);
    } else {
      current.right = _insert(value, current.right);
    }

    return current;
  }

  @override
  bool search(int value) {
    return _search(value, root);
  }

  bool _search(int value, BinarySearchTreeImpl? current) {
    if (current == null) {
      return false;
    }

    if (value < current.value) {
      return _search(value, current.left);
    } else if (value > current.value) {
      return _search(value, current.right);
    } else {
      return true;
    }
  }

  @override
  void delete(int value) {
    root = _delete(value, root);
  }

  BinarySearchTreeImpl? _delete(int value, BinarySearchTreeImpl? current) {
    if (current == null) {
      return current;
    }

    if (value < current.value) {
      current.left = _delete(value, current.left);
    } else if (value > current.value) {
      current.right = _delete(value, current.right);
    } else {
      if (current.left != null && current.right != null) {
        int min = current.right!.value;
        BinarySearchTreeImpl? leftMin = current.right!.left;
        current.right = leftMin;
        current.value = min;
        current.left = _delete(value, current.left);
      } else if (current.left != null) {
        current = current.left;
      } else if (current.right != null) {
        current = current.right;
      } else {
        current = null;
      }
    }

    return current;
  }
}

