    [0, 1, 2, 3],
    [1, 0, 4, 5],
    [2, 4, 0, 6],
    [3, 5, 6, 0],
  ];

  int n = dist.length;
  List<int> cities = List<int>.generate(n - 1, (i) => i + 1);

  int minCost = 1 << 30;
  List<int> minPath = [];

  void permute(List<int> arr, int l) {
    if (l == arr.length - 1) {

      int cost = 0;
      for (int i = 0; i < arr.length - 1; i++) {
        cost += dist[arr[i]][arr[i + 1]];
      }
      cost += dist[arr[arr.length - 1]][arr[0]];

