        arr = List<int>.from(arr);
        int tmp = arr[l];
        arr[l] = arr[i];
        arr[i] = tmp;
        permute(arr, l + 1);
        arr[i] = arr[l];
        arr[l] = tmp;
      }
    }
  }

  permute(cities, 0);

  if (minPath.isNotEmpty) {
    print('Minimum cost: $minCost');
    print('Path: ${minPath.join(' -> ')}');
