          recPrefs[p] = pPrefs;
        }
        final double cosine = cosineSim(recPrefs, u, item);
        simScore[item] = (simScore[item] ?? 0.0) + cosine;
      }
    }

    final List<String> sorted = simScore.keys.toList()..sort();
    print('Recommendations for $user:');
