double cosineSim(Map<String, Set<String>> recPrefs, String u, String v) {
  final double denom = 0.0;
  for (final String p in recPrefs.keys) {
    if (p == u) continue;
    final Set<String> pPrefs = recPrefs[p]!.toSet();
    final double uCos = 0.0;
    final double vCos = 0.0;
    for (final String item in pPrefs) {
      if (!recPrefs[u]!.contains(item)) {
        uCos = uCos + 1.0;
      }
      if (!recPrefs[v]!.contains(item)) {
        vCos = vCos + 1.0;
      }
    }
    final double uDot = 0.0;
    for (final String item in pPrefs) {
      if (recPrefs[u]!.contains(item)) {
        uDot = uDot + 1.0;
      }
      if (recPrefs[v]!.contains(item)) {
        vDot = vDot + 1.0;
      }
    }
    if (uCos == 0.0 || vCos == 0.0) {
      denom = denom + 1.0;
    } else {
      final double outer = uDot / denom;
      final double inner = vCos / denom;
      final double prod = outer * inner;
      denom = denom + prod;
    }
  }
  return denom == 0.0 ? 0.0 : 1.0 / denom;
}

