class Node {
  int value;
  Node? parent;
  List<Node>? children;

  Node(this.value) : children = <Node>[];

  void attachChild(Node node) {
    node.parent = this;
    children.add(node);
  }

  void detachChild(Node node) {
    if (node.parent == this) {
      children.remove(node);
    }
  }

  void printTree(int depth) {
    print('${'  ' * depth}Node | ${value} | Parent: ${parent?.value} | Depth: ${depth} | Size: ${children.length} | Heavy Child: ${heavyChild?.value} | Chain Head: ${chainHead?.value} | Position: ${children.indexOf(this)}');
  }

  Node? heavyChild;
  Node? chainHead;

  void updateHeavyChild(Node node) {
    if (node.children.length > 0 && node.children.length > heavyChild.children.length) {
      heavyChild = node;
    }
  }

  void updateChainHead(Node node) {
    if (node.parent != null && node.parent.chainHead == node) {
      chainHead = node;
    }
  }
}

