class Node {
  final List<String> children;
  final String value;

  Node(this.children, [this.value = '']);
}

class AI {
  String currentSymbol = 'O';

  String get opponent {
    return currentSymbol == 'O' ? 'X' : 'O';
  }

  Node get root => _getRoot();

  void switchSymbols() {
    currentSymbol = (currentSymbol == 'O') ? 'X' : 'O';
  }

  Node _getBestNode() {
    Node best = Node([]);
    int bestScore = -1000000;

    for (var node in best.children) {
      int score = _getScore(node);
      if (score > bestScore) {
        bestScore = score;
        best = node;
      }
    }

    return best;
  }

  int _getScore(Node node) {
    if (node.value.isEmpty) {
      return -1;
    }

    if (node.value == 'O') {
      return 10 - node.children.length;
    }

    if (node.value == 'X') {
      return node.children.length - 10;
    }

    return -1;
  }

  void printBoard(Node node) {
    if (node.value.isEmpty) {
      print(' | '.repeat(node.children.length));
      for (int i = 0; i < node.children.length; i++) {
        print('${node.children[i]} | '.repeat(node.children.length - 1));
      }
      print('');
    } else {
      print('${node.value} | '.repeat(node.children.length - 1));
    }
  }

  Node _getBestNodeRecursively(Node node, int depth) {
    if (depth == 0 || node.children.isEmpty) {
      return node;
    }

    int bestScore = -1000000;
    Node best = node;

    for (var child in node.children) {
      Node childNode = _getBestNodeRecursively(child, depth - 1);
      int score = _getScore(childNode);
      if (score > bestScore) {
        bestScore = score;
        best = childNode;
      }
    }

    return best;
  }

  Node _getBestNodeIterative(Node node) {
    var current = node;
    var best = node;

    while (current != null && current.children.isNotEmpty) {
      current = _getBestNodeRecursively(current, 1);
    }

    return best;
  }

  Node _getBestNodeMinimax(Node node, int depth, bool maximizing) {
    if (depth == 0) {
      return node;
    }

    if (maximizing) {
      int maxEval = -1000000;
      Node best = node;

      for (var child in node.children) {
        int eval = _getBestNodeMinimax(child, depth - 1, false).value.isEmpty ? -1 : 1;
        if (eval > maxEval) {
          maxEval = eval;
          best = child;
        }
      }

