      }
    }

    final double density = total / (w * h);
    if (density >= minDensity) {
      score += (density - minDensity) * 4.0;
    }

    final double memoValue = score + (threshold - t) / 8.0;
    memo[key] = memoValue;
    return memoValue;
  }

  return calculate(width, height, threshold, minDensity);
}

