  int lastFloor = -1;
  int direction = -1;

  for (int i = 0; i < log.length; i++) {
    String ch = log[i];
    if (ch == 'U') {
      direction = 1;
      floor++;
    } else if (ch == 'D') {
      direction = -1;
      floor--;
    } else if (ch == '!') {
      if (i + 1 < log.length) {
        String next = log[i + 1];
        if (next == '!') {
