        int digit = int.parse(ch);
        if (direction != -1) {
          floor += direction * digit;
        }
        checksumVal = (checksumVal * 10 + digit) % 97;
      } else {
        invalid++;
      }
    }
  }

  served = floor == lastFloor ? served - 1 : served;
  return {
    'served': served,
    'invalid': invalid,
    'checksum': checksumVal,
    'finalFloor': floor,
  };
}

