Map<String, int> fn0(String sequence, int modulus) {
  int served = 0;
  int checksum = 0;
  int finalFloor = -1;
  int invalid = 0;

  for (int i = 0; i < sequence.length; i++) {
    String letter = sequence[i];
    if (letter != 'D' && letter != 'U') {
      invalid++;
      continue;
    }

    int floor = -1;
    for (int j = i + 1; j < sequence.length; j++) {
      String digit = sequence[j];
      if (digit.codeUnitAt(0) >= 48 && digit.codeUnitAt(0) <= 57) {
        floor = floor * 10 + (digit.codeUnitAt(0) - 48);
      } else {
        break;
      }
    }

    if (floor == -1) {
      invalid++;
      continue;
    }

    if (floor % modulus != 0) {
      invalid++;
      continue;
    }

    if (letter == 'D') {
      if (floor > finalFloor) {
        finalFloor = floor;
      }
      served++;
      checksum = (checksum + floor) % modulus;
    } else {
      if (floor < finalFloor) {
        finalFloor = floor;
      }
      served--;
      checksum = (checksum - floor) % modulus;
    }

    i = j - 1;
  }

  return {
    'served': served,
    'checksum': checksum,
    'finalFloor': finalFloor,
    'invalid': invalid,
  };
}

