Map<String, int> fn0(String encoded, int checksum) {
  int served = 0;
  int invalid = 0;
  int finalFloor = 0;
  int? lastChecksum;
  int multiplier = 1;

  for (int i = 0; i < encoded.length; i++) {
    String ch = encoded[i];
    if (ch == 'U') {
      multiplier *= 2;
    } else if (ch == 'D') {
      multiplier /= 2;
    } else if (ch == '!') {
      if (i + 1 < encoded.length) {
        String next = encoded[i + 1];
        if (next == 'D') {
          multiplier = 2;
          i++;
        } else if (next == 'U') {
          multiplier = 1;
          i++;
        }
      }
    } else if (ch.codeUnitAt(0) >= 65 && ch.codeUnitAt(0) <= 90) {
      finalFloor = ch.codeUnitAt(0) - 64;
    } else if (ch.codeUnitAt(0) >= 48 && ch.codeUnitAt(0) <= 57) {
      int digit = int.parse(ch);
      if (digit < 0 || digit > 9) {
        invalid++;
      } else {
        if (lastChecksum != null) {
          int sum = 0;
          for (int j = 0; j < 2; j++) {
            sum += (lastChecksum!.codeUnitAt(j) - 65 + digit) * multiplier;
          }
          if (sum % 100 == checksum) {
            served++;
          } else {
            invalid++;
          }
        }
        lastChecksum = (lastChecksum ?? StringBuffer())
          ..writeCharCode(65 + (digit % 10))
          ..writeCharCode(65 + (digit ~/ 10));
      }
    } else {
      invalid++;
    }
  }

  return {
    'served': served,
    'invalid': invalid,
    'finalFloor': finalFloor,
  };
}

