Map<String, int> fn0(String stream, int floor) {
  int served = 0;
  int checksum = 0;
  int invalid = 0;
  int finalFloor = floor;

  for (String token in stream.split(',')) {
    if (token.isEmpty) continue;

    List<String> parts = token.split(':');
    if (parts.length != 2) {
      invalid++;
      continue;
    }

    String type = parts[0];
    String payload = parts[1];

    if (type != 'U' && type != 'D') {
      invalid++;
      continue;
    }

    int? value = int.tryParse(payload);
    if (value == null) {
      invalid++;
      continue;
    }

    if (value > floor) {
      finalFloor = value;
    } else if (value < floor) {
      if (type == 'U') {
        finalFloor = floor;
      } else {
        finalFloor = floor - value.abs();
      }
    }

    if (type == 'U') {
      served += value;
      checksum = (checksum + value) % floor + 1;
    } else {
      served += value;
      checksum = (checksum - value) % floor + 1;
    }
  }

  return {'served': served, 'checksum': checksum, 'finalFloor': finalFloor, 'invalid': invalid};
}

