import 'dart:math';

class Point {
  final double x;
  final double y;

  Point(this.x, this.y);
}

class Triangle {
  final List<Point> vertices;
  final double area;

  Triangle(this.vertices, [this.area = 0.0]);
}

class DelaunayTriangulation {
  final List<Point> points;

  DelaunayTriangulation(this.points);

  List<Triangle> _build(List<Point> points) {
    final random = Random(0);
    final n = points.length;
    if (n <= 3) return [];

    final List<Triangle> triangles = [];

    for (int i = 0; i < n; i++) {
      final j = random.nextInt(n);

      if (i == j) continue;

      final k = random.nextInt(n);

      while (k == j || k == i) {
        k = random.nextInt(n);
      }

      final a = points[i];
      final b = points[j];
      final c = points[k];

      final double sa = (a.x - b.x) * (c.y - b.y);
      final double sb = (b.x - c.x) * (a.y - b.y);
      final double sc = (c.x - a.x) * (b.y - c.y);

      final double area = (sa + sb + sc) / 2.0;

      if (area >= 1e-12) {
        triangles.add(Triangle(
          [a, b, c],
          area,
        ));
      }
    }

    return triangles;
  }

  void _drawTriangles(List<Triangle> triangles, String filename) {
    final svg = StringBuffer();

    svg.writeln('<?xml version="1.0" encoding="UTF-8" ?>');
    svg.writeln('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 500 500">');

    for (var t in triangles) {
      final xs = t.vertices.map((v) => v.x).toList();
      final ys = t.vertices.map((v) => v.y).toList();

      svg.writeln('<polygon points="${xs.join(',')} ${ys.join(',')} fill="none" stroke="black" stroke-width="1"/>');
    }

    svg.writeln('</svg>');

    final file = File(filename);
    file.writeAsStringSync(svg.toString());

    print('SVG output to $filename');
  }

  void draw(String filename) {
    final triangles = _build(points);
    _drawTriangles(triangles, filename);
  }

  void printTriangles() {
    final triangles = _build(points);
    print('Delaunay Triangulation of ${points.length} points:');
    for (final t in triangles) {
      print('Triangle(${t.vertices.map((v) => v.x).join(',')} ${t.vertices.map((v) => v.y).join(',')} height=${t.area})');
    }
  }
}

