class SkipListNode {
  final int value;
  final List<SkipListNode?> forwardLinks;

  SkipListNode(this.value, [this.forwardLinks = const []]);
}

class SkipList {
  final Random random = Random(0);

  final List<SkipListNode?> levels = [null];
  int currentLevel = 0;

  void add(int value) {
    if (value < 0) {
      return;
    }

    final int level = currentLevel;
    final int hash = value % (1 << level);
    SkipListNode? node = levels[level]..forwardLinks[hash];

    if (node == null) {
      levels[level] = SkipListNode(value, [node, null]);
      currentLevel++;
    } else {
      node.forwardLinks.add(SkipListNode(value, [node.forwardLinks[hash], null]));
    }
  }

  bool search(int value) {
    if (value < 0) {
      return false;
    }

    final int level = currentLevel;
    final int hash = value % (1 << level);
    SkipListNode? node = levels[level]..forwardLinks[hash];

    while (node != null) {
      if (node.value == value) {
        return true;
      }
      node = node.forwardLinks[hash];
    }
    return false;
  }

  bool delete(int value) {
    if (value < 0) {
      return false;
    }

    final int level = currentLevel;
    final int hash = value % (1 << level);
    SkipListNode? node = levels[level]..forwardLinks[hash];

    while (node != null) {
      if (node.value == value) {
        final SkipListNode? parent = node.forwardLinks[hash - 1];
        if (parent != null) {
          (parent as SkipListNode).forwardLinks.remove(node);
          return true;
        }
        return false;
      }
      node = node.forwardLinks[hash];
    }
    return false;
  }

  void printList() {
    print('Skip List:');
    for (int i = 0; i < levels.length; i++) {
      print('Level $i: ${levels[i]}');
    }
    print('');
  }
}

