double fn0(List<int> floorRequests, List<int> serviceCenters, int maxDistance) {
  if (floorRequests.isEmpty || serviceCenters.isEmpty) {
    return 0.0;
  }

  if (maxDistance < 0) {
    return 0.0;
  }

  List<List<int>> centers = [];
  for (int i = 0; i < serviceCenters.length; i++) {
    centers.add([serviceCenters[i], i]);
  }

  int n = floorRequests.length;
  List<double> distances = [];

  for (int i = 0; i < n; i++) {
    int request = floorRequests[i];

    List<List<int>> candidates = [];
    for (var center in centers) {
      int dist = (request - center[0]).abs();
      if (dist <= maxDistance) {
        candidates.add([dist, center[1]]);
      }
    }

    if (candidates.isEmpty) {
      distances.add(0.0);
    } else {
      candidates.sort((a, b) {
        double da = a[0].toDouble();
        double db = b[0].toDouble();
        if (da != db) {
          return da.compareTo(db);
        }
        return a[1].compareTo(b[1]);
      });
      distances.add(candidates[0][0]);
    }
  }

  double total = 0.0;
  for (double d in distances) {
    total += d;
  }

  return total / n;
}

