class Perceptron {
  List<double> weights = [0.0, 0.0];
  double bias = 0.0;

  double predict(List<double> x) {
    double sum = bias;
    for (int i = 0; i < weights.length; i++) {
      sum += weights[i] * x[i];
    }
    return sum >= 0 ? 1.0 : 0.0;
  }

  void train(List<List<double>> inputs, List<double> targets, int epochs, double learningRate) {
    double error = 1e+21;
    int epoch = 0;

    while (error > 1e-4 && epoch < epochs) {
      error = 0.0;
      epoch++;

      for (var input in inputs) {
        double output = predict(input);
        double error = targets[input.length - 1] - output;
        if (error != 0) {
          for (int i = 0; i < weights.length; i++) {
            weights[i] += learningRate * error * input[i];
          }
          bias += learningRate * error;
          error = 0.0;
        }
      }
    }

    print('Trained perceptron model:');
    print('Weights: $weights');
    print('Bias: $bias');
  }
}

