  const doubleMap = {'P': 1.5, 'Q': 2.5};

  List<String> tokens = recipe.split(' ');
  List<List<String>> ingredients = [];
  for (String token in tokens) {
    if (token.isEmpty) continue;

    String trimmed = token.trim();
    if (trimmed.isEmpty) continue;

    String letter = trimmed[0];
    int? numericValue;
    String? doubleString;

    if (intMap.containsKey(letter)) {
      numericValue = intMap[letter];
    } else if (doubleMap.containsKey(letter)) {
      doubleString = doubleMap[letter];
    }

