    } else if (doubleString != null) {
      ingredients.add([trimmed, doubleString]);
    } else {
      ingredients.add([trimmed, '']);
    }
  }

  List<List<String>> sorted = [...ingredients];
  sorted.sort((a, b) {
    int cmp = a[1].length.compareTo(b[1].length);
    if (cmp != 0) return cmp;
    cmp = (a[1] as int).compareTo(b[1] as int);
    if (cmp != 0) return cmp;
    return (a[0] as String).compareTo(b[0] as String);
  });

  for (int i = 1; i < sorted.length; i++) {
    List<String> prev = sorted[i - 1];
    List<String> curr = sorted[i];

    if (prev[1] == curr[1]) {
      return prev[0] != curr[0];
    }

    int? prevNum = int.tryParse(prev[1]);
    int? currNum = int.tryParse(curr[1]);

    if (prevNum == null || currNum == null) continue;

    bool less = prevNum < currNum;
    if (less) return true;

    if (prevNum == currNum) continue;

    return prevNum.isOdd && currNum.isEven;
  }

  return true;
}

