bool fn0(List<int> sortedDurations, int targetSeconds) {
  if (sortedDurations.isEmpty) return false;
  Map<int, int> counts = {};
  for (int d in sortedDurations) {
    counts[d] = (counts[d] ?? 0) + 1;
  }
  int targetCount = targetSeconds ~/ 60;
  List<int> sortedDurations = counts.keys.toList()..sort();
  for (int i = 0; i < sortedDurations.length; i++) {
    int count = counts[sortedDurations[i]]!;
    if (count >= targetCount) {
      int index = sortedDurations.indexOf(sortedDurations[i]);
      int prev = (i == 0) ? -1 : sortedDurations[i - 1];
      int next = (i == sortedDurations.length - 1) ? -1 : sortedDurations[i + 1];
      if ((prev == -1 && next != -1) ||
          (prev != -1 && next == -1) ||
          (prev != -1 && next != -1 && prev != next)) {
        return true;
      }
    }
  }
  return false;
}

