void fn0(List<String> args) {

  if (args.length != 1) {
    print('Usage: dart fn0 <seed hex>');
    return;
  }

  String seed = args[0];
  if (seed.length != 6) {
    print('Invalid hex seed.');
    return;
  }

  int seedR = int.parse(seed.substring(0, 2), radix: 16);
  int seedG = int.parse(seed.substring(2, 4), radix: 16);
  int seedB = int.parse(seed.substring(4, 6), radix: 16);

  double seedH = ((seedR << 16) | (seedG << 8) | seedB) / 255.0;

  double hue2rgb(double p, double q, double t) {
    if (t < 0.0) t += 1.0;
    if (t > 1.0) t -= 1.0;
    if (t < 1.0 / 6.0) return p + (q - p) * 6 * t;
    if (t < 1.0 / 2.0) return q;
    if (t < 1.0 / 3.0) return p + (q - p) * (2.0 / 3.0 - t) * 6;
    return p;
  }

  double lChroma(double h) {
    if (h < 0.0) h += 1.0;
    if (h < 1.0 / 6.0) return h * 6;
    if (h < 1.0 / 2.0) return 1.0 - (1.0 - h) * 4.0;
    if (h < 1.0 / 3.0) return 1.0 - (1.0 - h) * 2.0;
    return 1.0;
  }

  double saturation(double h) {
    if (h < 0.0) h += 1.0;
    if (h < 1.0 / 6.0) return 0.0;
    if (h < 1.0 / 2.0) return (1.0 - lChroma(h)) * 2.0;
    if (h < 1.0 / 3.0) return 1.0 - (1.0 - h) * 2.0;
    return (1.0 - lChroma(h)) * 4.0;
  }

  double brightness(double h) {
    if (h < 0.0) h += 1.0;
    if (h < 1.0 / 6.0) return 0.0;
    if (h < 1.0 / 2.0) return lChroma(h) * 2.0;
    if (h < 1.0 / 3.0) return 1.0 - (1.0 - h) * 2.0;
    return 1.0;
  }

  double h255(double h) {
    return brightness(h) * 255.0;
  }

  double lChroma255(double h) {
    return lChroma(h) * 255.0;
  }

  double saturation255(double h) {
    return saturation(h) * 255.0;
  }

  double brightness255(double h) {
    return brightness(h) * 255.0;
  }

  double h360(double h) {
    if (h < 0.0) h += 1.0;
    if (h >= 360.0) h -= 360.0;
    return h;
  }

  double chroma360(double h) {
    if (h < 180.0) return 360.0 - h;
    return h - 180.0;
  }

  print('Seed: #${seed.padRight(6, '0')}');
  print('  H: ${h255(seedH).toRadixString(16).padLeft(6, '0')}');
  print('  S: ${saturation255(seedH).toRadixString(16).padLeft(6, '0')}');
  print('  L: ${brightness255(seedH).toRadixString(16).padLeft(6, '0')}');

  double hue = seedH + 60.0;
  double l360 = h360(hue);

  print('\nAnalogous +30°');
  print('  H: ${h255(l360).toRadixString(16).padLeft(6, '0')}');
  print('  S: ${saturation255(l360).toRadixString(16).padLeft(6, '0')}');
  print('  L: ${brightness255(l360).toRadixString(16).padLeft(6, '0')}');

  double h240 = h360(hue) + 240.0;
  print('\nTriadic +240°');
  print('  H: ${h255(h240).toRadixString(16).padLeft(6, '0')}');
  print('  S: ${saturation255(h240).toRadixString(16).padLeft(6, '0')}');
  print('  L: ${brightness255(h240).toRadixString(16).padLeft(6, '0')}');

  double h120 = h360(hue) + 120.0;
  print('\nTriadic +120°');
  print('  H: ${h255(h120).toRadixString(16).padLeft(6, '0')}');
  print('  S: ${saturation255(h120).toRadixString(16).padLeft(6, '0')}');
  print('  L: ${brightness255(h120).toRadixString(16).padLeft(6, '0')}');

  double h210 = h360(hue) + 210.0;
  print('\nAnalogous -30°');
  print('  H: ${h255(h210).toRadixString(16).padLeft(6, '0')}');
  print('  S: ${saturation255(h210).toRadixString(16).padLeft(6, '0')}');
  print('  L: ${brightness255(h210).toRadixString(16).padLeft(6, '0')}');

  double h180 = h360(hue) + 180.0;
  print('\nComplement');
  print('  H: ${h255(h180).toRadixString(16).padLeft(6, '0')}');
  print('  S: ${saturation255(h180).toRadixString(16).padLeft(6, '0')}');
