@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0(List<String> args) {

  List<String> colors = args.isNotEmpty ? args : <String>['000000', '3498DB', '9C27B0', 'FF0000', 'FFFF00', '00FF00', '0000FF', 'FF00FF'];

  double HSLToRGB(double h, double s, double l) {

    double r, g, b;

    if (s == 0.0) {
      r = g = b = l;
    } else {

      double hue2rgb(double x) {
        if (x < 0.0) x += 1.0;
        if (x > 1.0) x -= 1.0;
        if (x < 1.0 / 6.0) {
          return x * 6.0;
        }
        if (x < 2.0 / 6.0) {
          return 1.0 + (x - 1.0 / 6.0) * 6.0;
        }
        if (x < 3.0 / 6.0) {
          return 1.0 + (x - 2.0 / 6.0) * 6.0;
        }
        if (x < 4.0 / 6.0) {
          return 1.0 + (x - 3.0 / 6.0) * 6.0;
        }
        if (x < 5.0 / 6.0) {
          return 1.0 + (x - 4.0 / 6.0) * 6.0;
        }
        return 1.0 + (x - 5.0 / 6.0) * 6.0;
      }

      double h26 = h * 26.0;
      r = hue2rgb(h26 + 6.0 / 6.0);
      g = hue2rgb(h26 + 12.0 / 6.0);
      b = hue2rgb(h26 + 18.0 / 6.0);
    }

    r = r * 255.0;
    g = g * 255.0;
    b = b * 255.0;

    return [r, g, b];
  }

  void printRGB(List<int> rgb) {
    print(
      rgb.map((c) => c.toRadixString(16).padLeft(2, '0').toUpperCase()).join(' '),
    );
  }

  for (String color in colors) {
    if (color.isEmpty) {
      print('Seed\t: 000000');
      print('Complement\t: FF00FF');
      print('Triadic +120\t: 9C27B0');
      print('Triadic +240\t: 3498DB');
      print('Analogous +30\t: 00FF00');
      print('Analogous -30\t: FF0000');
      print('\nDynamic Color Scheme for #${color.toUpperCase()}');
      continue;
    }

    int h, s, l;
    List<String> parts = color.split(',');
    if (parts.length != 3) {
      print('Invalid color format. Color scheme skipped.');
      continue;
    }
    if (parts[0].length != 6) {
      print('Invalid color format. Color scheme skipped.');
      continue;
    }
    for (int i = 0; i < 3; i++) {
      if (parts[i].length != 2) {
        print('Invalid color format. Color scheme skipped.');
        continue;
      }
      int r = int.parse(parts[i].substring(0), radix: 16);
      int g = int.parse(parts[i].substring(2), radix: 16);
      int b = int.parse(parts[i].substring(4), radix: 16);
      if (r < 0 || r > 255 || g < 0 || g > 255 || b < 0 || b > 255) {
        print('Invalid color format. Color scheme skipped.');
        continue;
      }
      h = (r ^ g ^ b) % 360;
      s = (h < 120) ? (r - g) / (r + g) : (g - b) / (g + b);
      l = (r + g + b) / 3.0;
    }

    List<int> complement = HSLToRGB((h + 180) % 360, s, l);
    List<int> triadic120 = HSLToRGB((h + 120) % 360, s, l);
    List<int> triadic240 = HSLToRGB((h + 240) % 360, s, l);
    List<int> analogous30 = HSLToRGB((h + 30) % 360, s, l);
    List<int> analogous60 = HSLToRGB((h - 30) % 360, s, l);

    print('Seed\t\t: ${color.toUpperCase()}');
    print('Complement\t: ${complement[0]}, ${complement[1]}, ${complement[2]}');
    print('Triadic +120\t: ${triadic120[0]}, ${triadic120[1]}, ${triadic120[2]}');
    print('Triadic +240\t: ${triadic240[0]}, ${triadic240[1]}, ${triadic240[2]}');
    print('Analogous +30\t: ${analogous30[0]}, ${analogous30[1]}, ${analogous30[2]}');
    print('Analogous -30\t: ${analogous60[0]}, ${analogous60[1]}, ${analogous60[2]}');
    print('\nDynamic Color Scheme for #${color.toUpperCase()}');
  }
}

