class ColorScheme {
  final int seed;

  ColorScheme(this.seed);

  Iterable<String> map(String key, int multiplier) {
    final result = <String>[];
    for (final value in seedColors) {
      if (key == 'Seed') {
        result.add('#${value.toRadixString(16).toUpperCase().padLeft(6, '0')}');
      } else {
        result.add('#${(value + (key == "Darker" ? -multiplier : multiplier))
            .toRadixString(16).toUpperCase().padLeft(6, '0')}');
      }
    }
    return result;
  }

  Iterable<int> get seedColors {
    final values = <int>[seed];
    for (var i = 0; i < 8; i++) {
      final next = <int>[];
      for (final v in values) {
        if (i == 0) {
          next.add(v + (v == 0 ? 30 : -30));
        } else {
          next.add(v >> 16 | v & 0xFFFFFF | v & 0xFFFFFF);
        }
      }
      values = next;
    }
    return values;
  }
}

extension on int {
  int toRadixString(int radix) {
    var result = 0;
    for (var i = 0; i < 8; i++) {
      result = result * radix + (this >> (i * 6)) & 0xFF;
    }
    return result;
  }

  String toHex(int radix) {
    return result.toRadixString(16).toUpperCase().padLeft(6, '0');
  }
}

