@pragma('vm:never-inline')
@pragma('vm:entry-point')
void fn0() {

  final rand = Random(0);
  const int popSize = 100;
  const int generations = 100;
  const double mutationRate = 0.01;
  const int eliteSize = 20;

  final String target = "HELLO WORLD";
  final int targetLen = target.length;

  final List<String> population = List.generate(
    popSize,
    (i) => rand.nextInt(16).toRadixString(16),
  );

  int fitness(String individual) {
    int fitness = 0;
    for (int i = 0; i < targetLen; i++) {
      if (individual[i] == target[i]) fitness++;
    }
    return fitness;
  }

  String tournamentSelection() {
    final List<String> candidates = List<String>.generate(
      eliteSize,
      (i) => population[i],
    );

    candidates.sort((a, b) {
      final fitA = fitness(a);
      final fitB = fitness(b);
      if (fitA != fitB) return fitB.compareTo(fitA);
      return a.compareTo(b);
    });

    return candidates[0];
  }

  String crossover(String parent1, String parent2) {
    final int crossoverPoint = rand.nextInt(targetLen);
    final String child = parent1.substring(0, crossoverPoint) + 
                        parent2.substring(crossoverPoint);

    return child;
  }

  String mutate(String individual) {
    final String mutated = individual.split('')
      ..map((c) {
        if (rand.nextDouble() < mutationRate) {
          return String.fromCharCode((c.codeUnitAt(0) + rand.nextInt(26)) % 26 + 97);
        }
        return c;
      })
      ..join();

    return mutated;
  }

  String bestIndividual = "";
  int bestFit = 0;

  for (int gen = 0; gen < generations; gen++) {

    List<String> newPopulation = [];

    for (int i = 0; i < eliteSize; i++) {
      newPopulation.add(population[i]);
    }

    while (newPopulation.length < popSize) {

      String parent1 = tournamentSelection();
      String parent2 = tournamentSelection();

      String child = crossover(parent1, parent2);
      child = mutate(child);

      newPopulation.add(child);
    }

    population = newPopulation;

    for (int i = 0; i < popSize; i++) {
      final fit = fitness(population[i]);
      if (fit > bestFit) {
        bestFit = fit;
        bestIndividual = population[i];
      } else if (fit == bestFit) {
        if (population[i].compareTo(bestIndividual) < 0) {
          bestIndividual = population[i];
        }
      }
    }

    print("Generation $gen - Best: $bestIndividual (Fitness: $bestFit)");
    if (bestFit == targetLen) {
      print("Target found in generation $gen!");
      break;
    }
  }

  if (!bestFit.isEven) {
    print("Target not found after $generations generations");
  }

  print("\nFinal Statistics:");
  print("Best individual: $bestIndividual");
  print("Best fitness: $bestFit");
  print("Total generations: $generations");
  print("Mutation rate: $mutationRate");
  print("Elite size: $eliteSize");
  print("Population size: $popSize");
}

