        fitness++;
      }
    }
    return fitness;
  }

  String tournamentSelection(List<String> population) {
    List<String> tournament = [];
    for (int i = 0; i < 5; i++) {
      tournament.add(population[rng.nextInt(population.length)]);
    }
    tournament.sort((a, b) {
      int fA = calculateFitness(a);
      int fB = calculateFitness(b);
      if (fA != fB) return fB.compareTo(fA);
      return a.compareTo(b);
    });
    return tournament[0];
  }

  String crossover(String parent1, String parent2) {
    int crossoverPoint = rng.nextInt(parent1.length);
    return parent1.substring(0, crossoverPoint) + 
           parent2.substring(crossoverPoint);
  }

  String mutate(String individual) {
    List<String> chars = individual.split('');
    for (int i = 0; i < chars.length; i++) {
      if (rng.nextDouble() < mutationRate) {
        chars[i] = chars[i] == chars[i][0] ? chars[i][0].toUpperCase() : chars[i][0];
      }
    }
    return chars.join('');
  }

