        bestIndividual = individual;
      } else if (fitness == bestFitness && 
                individual.length < bestIndividual.length) {
        bestIndividual = individual;
      } else if (fitness == bestFitness && 
                individual.length == bestIndividual.length && 
                individual.compareTo(bestIndividual) < 0) {
        bestIndividual = individual;
      }
