    populationSize,
    (_) =>
        List<int>.generate(target.length, (i) => i < target.length ? target[i] : '_').join()
  );

  int fitness(String individual) {
    int fitness = 0;
    for (int i = 0; i < individual.length; i++) {
      if (individual[i] == target[i]) {
        fitness++;
      }
    }
    return fitness;
  }

  String tournamentSelect(List<String> population) {
    List<String> tournament = [];
    for (int i = 0; i < 5; i++) {
      int j = Random(0).nextInt(population.length);
      tournament.add(population[j]);
    }
    tournament.sort((a, b) {
      int aFit = fitness(a);
      int bFit = fitness(b);
      if (aFit != bFit) return bFit.compareTo(aFit);
      return a.compareTo(b);
    });
    return tournament[0];
  }

  void mutate(String individual) {
    for (int i = 0; i < individual.length; i++) {
      if (Random(0).nextDouble() < mutationRate) {
        individual = individual.substring(
            0, i) + individual[i] + individual.substring(i + 1);
      }
