    while (queue.isNotEmpty) {
      int u = queue.removeFirst();
      for (int v in g[u] ?? []) {
        if (!visited.contains(v)) {
          visited.add(v);
          queue.add(v);
        }
      }
    }

    return visited.length == g.length;
  }

  void findEulerian(Map<int, List<int>> g, String type) {
    if (!isConnected(g)) {
      print('Graph is not connected');
