void fn0() {

  const int populationSize = 30;
  const double mutationRate = 0.01;
  const int generations = 100;
  const int chromosomeLength = 10; 
  const int tournamentSize = 3;

  final rng = Random(0);

  List<List<int>> population = [];
  for (int i = 0; i < populationSize; i++) {
    List<int> individual = List<int>.generate(chromosomeLength, (_) => rng.nextBool() ? 1 : 0);
    population.add(individual);
  }

  int fitness(List<int> individual) {
    int fit = 0;
    for (int i = 0; i < individual.length; i++) {
      if (individual[i] == 1) fit++;
    }
    return fit;
  }

  List<int> tournamentSelect(List<List<int>> population) {

    List<List<int>> tournament = [];

    for (int i = 0; i < tournamentSize; i++) {
      int j = rng.nextInt(population.length);
      tournament.add(population[j]);
    }

    tournament.sort((a, b) {
      int fa = fitness(a);
      int fb = fitness(b);
      if (fa != fb) return fb - fa;
      return b.length - a.length; 
    });
    return tournament.first;
  }

  List<int> crossover(List<int> parent1, List<int> parent2) {
    int point = rng.nextInt(chromosomeLength - 1) + 1;
    List<int> child = List<int>.from(parent1);
    child.addAll(parent2.sublist(point));
    return child;
  }

  List<int> mutate(List<int> individual) {
    List<int> mutated = List<int>.from(individual);
    for (int i = 0; i < mutated.length; i++) {
      if (rng.nextDouble() < mutationRate) {
        mutated[i] = 1 - mutated[i];
      }
    }
    return mutated;
  }

  int bestFit = -1;
  List<int>? bestIndividual;

  for (int gen = 1; gen <= generations; gen++) {
    List<List<int>> newPopulation = [];

    while (newPopulation.length < populationSize) {

      List<int> parent1 = tournamentSelect(population);
      List<int> parent2 = tournamentSelect(population);

      List<int> child = crossover(parent1, parent2);
      child = mutate(child);

      newPopulation.add(child);
    }

    population = newPopulation;

    int currentBest = population.reduce((a, b) {
      int af = fitness(a);
      int bf = fitness(b);
      return af > bf ? a : b;
    });

    int currentFit = fitness(currentBest);
    if (currentFit > bestFit) {
      bestFit = currentFit;
      bestIndividual = currentBest;
    }

    print('Generation $gen: Best Fitness = $bestFit');
  }

  if (bestIndividual != null) {
    print('Best individual: $bestIndividual');
  }
}

