class Individual {
  final List<bool> bits;
  int fitness = 0;

  Individual(this.bits);
}

class Population {
  final int size;
  final Random rng;
  List<Individual> population;

  Population(this.size, [this.rng = const Random(0)]);

  void initPopulation() {
    population = List.generate(size, (_) => Individual(List<bool>.filled(16, rng.nextBool())));
  }

  void selectParent() {
    final parents = List<Individual>.generate(2, (_) => population[rng.nextInt(population.length)]);
    return parents;
  }

  void crossover(Individual parent1, Individual parent2) {
    final crossoverPoint = rng.nextInt(parent1.bits.length);
    final child = Individual(List<bool>.from(parent1.bits));
    for (int i = 0; i < crossoverPoint; i++) {
      child.bits[i] = parent1.bits[i];
    }
    for (int i = crossoverPoint; i < parent2.bits.length; i++) {
      child.bits[i] = parent2.bits[i];
    }
    return child;
  }

  void mutate(Individual individual) {
    for (int i = 0; i < individual.bits.length; i++) {
      if (rng.nextDouble() < 0.01) {
        individual.bits[i] = !individual.bits[i];
      }
    }
  }

  void evaluateFitness() {
    for (var ind in population) {
      var fit = 0;
      for (var i = 0; i < ind.bits.length; i++) {
        if (ind.bits[i]) {
          fit++;
        }
      }
      ind.fitness = fit;
    }
  }

  Individual getBest() {
    var best = population[0];
    for (var ind in population) {
      if (ind.fitness > best.fitness) {
        best = ind;
      }
