void fn0() {

  final random = Random(0);

  const int populationSize = 30;
  const int chromosomeLength = 16; 
  const int generations = 100;
  const double mutationRate = 0.01;
  const double crossoverRate = 0.7;

  List<List<int>> population = List.generate(populationSize, (_) =>
      List<int>.generate(chromosomeLength, (_) => random.nextBool() ? 1 : 0));

  int fitness(List<int> chrom) {
    int fit = 0;
    for (int i = 0; i < chrom.length; i++) {
      if (chrom[i] == 1) fit++;
    }
    return fit;
  }

  List<List<int>> tournamentSelection(List<List<int>> pop) {
    final tournamentSize = 3;
    List<List<int>> winners = [];

    for (int i = 0; i < pop.length; i++) {

      List<int> select = [];
      for (int j = 0; j < tournamentSize; j++) {
        final idx = random.nextInt(pop.length);
        select.add(pop[idx]);
      }

      select.sort((a, b) => fitness(b) - fitness(a));
      winners.add(select.first);
    }
    return winners;
  }

  List<int> crossover(List<int> p1, List<int> p2) {
    if (random.nextDouble() > crossoverRate) {
      return List<int>.from(p1);
    }
    final crossoverPoint = random.nextInt(chromosomeLength);
    final child = <int>[];
    child.addAll(p1.sublist(0, crossoverPoint));
    child.addAll(p2.sublist(crossoverPoint));
    return child;
  }

  List<int> mutate(List<int> chrom) {
    for (int i = 0; i < chrom.length; i++) {
      if (random.nextDouble() < mutationRate) {
        chrom[i] = 1 - chrom[i];
      }
    }
    return chrom;
  }

  List<List<int>> bestPopulation = [];

  for (int gen = 0; gen < generations; gen++) {

    List<List<int>> newPopulation = [];
    while (newPopulation.length < populationSize) {

      List<int> p1 = tournamentSelection(bestPopulation);
      List<int> p2 = tournamentSelection(bestPopulation);

      final child = crossover(p1, p2);
      final childMutated = mutate(child);

      newPopulation.add(childMutated);
    }

    bestPopulation = newPopulation.map((chrom) => List<int>.from(chrom)).toList();

    print('Generation $gen: Best Fitness = ${bestPopulation.map((chrom) => fitness(chrom)).reduce((a, b) => a > b ? a : b)}');
  }

  print('Best individual: ${bestPopulation.map((chrom) => fitness(chrom)).reduce((a, b) => a > b ? a : b)}');
}

