void fn0() {

  final rng = Random(0);

  const int populationSize = 30;
  const int generations = 100;
  const double crossoverRate = 0.7;
  const double mutationRate = 0.01;
  const int chromosomeLength = 32;

  final List<List<int>> population = List.generate(
    populationSize,
    (_) => List.generate(chromosomeLength, (_) => rng.nextBool() ? 1 : 0),
  );

  final List<int> fitnesses = List<int>.generate(populationSize, (_) => 0);

  for (int generation = 0; generation < generations; generation++) {

    final List<List<int>> newPopulation = [];

    while (newPopulation.length < populationSize) {

      final int parent1 = rng.nextInt(populationSize);
      final int parent2 = rng.nextInt(populationSize);

      final List<int> child1 = List<int>.from(population[parent1]);
      final List<int> child2 = List<int>.from(population[parent2]);

      final int point = rng.nextInt(chromosomeLength);

      final int pointA = point < chromosomeLength ? point : chromosomeLength - 1;
      final int pointB = point < chromosomeLength ? chromosomeLength - 1 : point;


      for (int i = pointA; i < pointB; i++) {
        final double rand = rng.nextDouble();
        if (rand < crossoverRate) {

          final List<int> segment = child1.sublist(pointA, pointB);
          child2.addAll(segment);
        }
      }

      final List<int> mutateChild1 = List<int>.from(child1);
      final List<int> mutateChild2 = List<int>.from(child2);

      for (int i = 0; i < mutateChild1.length; i++) {
        if (rng.nextDouble() < mutationRate) {
          mutateChild1[i] = 1 - mutateChild1[i];
        }
        if (rng.nextDouble() < mutationRate) {
          mutateChild2[i] = 1 - mutateChild2[i];
        }
      }

      newPopulation.add(mutateChild1);
      newPopulation.add(mutateChild2);
    }

    population = newPopulation;

    fitnesses = List<int>.generate(populationSize, (i) {
      var fitness = 0;
      for (var bit in population[i]) {
        if (bit == 1) {
          fitness++;
        }
      }
      return fitness;
    });

    final int bestIndex = fitnesses.indexOf(fitnesses.reduce((a, b) => a > b ? a : b));

    print(
      'Generation $generation: Best Fitness = ${fitnesses[bestIndex]}',
    );
  }

  final List<List<int>> bestIndividual = population[bestIndex];
  print('Best individual: $bestIndividual');
}

