class Theme {
  String name;
  Map<String, String> colors;
  Theme(this.name, this.colors);
}

class ThemeManager {
  Map<String, Theme> _themeStore = {};
  List<String> _activeThemes = [];

  void setTheme(String themeName) {
    if (_themeStore.containsKey(themeName)) {
      _activeThemes.clear();
      _activeThemes.add(themeName);
    } else {
      print('Error: Theme "$themeName" not found. Current theme unchanged.');
    }
  }

  void setThemes(List<String> themeNames) {
    for (var themeName in themeNames) {
      setTheme(themeName);
    }
  }

  void addTheme(String name, Map<String, String> colors) {
    _themeStore[name] = Theme(name, colors);
    print('Added new theme: $name');
  }

  void removeTheme(String name) {
    if (_themeStore.containsKey(name)) {
      _themeStore.remove(name);
      print('Theme "$name" removed successfully');
    } else {
      print('Error: Theme "$name" not found. Theme removal failed.');
    }
  }

  void cycleTheme() {
    if (_activeThemes.isEmpty) {
      print('No theme currently set. Theme cycling demo skipped.');
    } else {
      print('\n--- Theme Cycling Demo ---');
      print('Current Theme: ${_activeThemes.first}');
      print('Available themes: ${_themeStore.keys.toList()}');
      int currentIdx = _activeThemes.indexOf(_activeThemes.first);
      String currentTheme = _activeThemes[currentIdx];

      List<int> sortedThemes = _themeStore.keys.toList()..sort();
      int nextIdx = (currentIdx + 1) % sortedThemes.length;
      String nextTheme = sortedThemes[nextIdx];

      print('Cycled to: $nextTheme');
      setTheme(nextTheme);
      print('\nSimulating UI with current theme:\n');
      print('  ${_themeStore[nextTheme].colors['background']} background');
      print('  ${_themeStore[nextTheme].colors['text']} text color');
      print('  ${_themeStore[nextTheme].colors['accent']} accent color');
    }
  }

  void displayAllThemes() {
    print('\n--- Available Themes ---');
    _themeStore.forEach((key, value) {
      print('  $key: ${value.name}');
    });
  }

  void displayActiveTheme() {
    if (_activeThemes.isEmpty) {
      print('No theme currently set');
    } else {
      print('Current Theme: ${_activeThemes.first}');
      print('  Primary Color: ${_themeStore[_activeThemes.first].colors['primary']}');
      print('  Background Color: ${_themeStore[_activeThemes.first].colors['background']}');
      print('  Text Color: ${_themeStore[_activeThemes.first].colors['text']}');
      print('  Accent Color: ${_themeStore[_activeThemes.first].colors['accent']}');
    }
  }

  void displayInvalidTheme() {
    print('\n--- Invalid Theme Handling ---');
    String invalidTheme = 'invalid_theme';
    try {
      setTheme(invalidTheme);
    } catch (e) {
      print('Error: Theme "$invalidTheme" not found. Current theme unchanged.');
    }
  }
}

