List<String> fn0(int grid, int lead, int age, int lag, List<int> data) {
  var out = <String>[];
  var i = 0;
  while (i < data.length) {
    var v = data[i];
    var d = data[i + 1];
    if (v == 0) {
      out.add('GRID_$grid: ERR_NO_DATA');
      i += 2;
      continue;
    }
    var gap = v.abs();
    var m = lag - gap;
    if (m < 0) {
      out.add('GRID_$grid: ERR_BAD_LAG');
      i += 2;
      continue;
    }
    var lo = i + m;
    var hi = i + age;
    if (lo >= data.length) {
      out.add('GRID_$grid: ERR_FUTURE');
      i += 2;
      continue;
    }
    var best = 0;
    for (var j = lo; j < hi; j++) {
      var c = data[j];
      if (c == 0) {
        i = j + 1;
        break;
      }
      var gap2 = c.abs();
      if (gap2 < gap) {
        gap = gap2;
        best = j;
      } else if (gap2 == gap) {
        if (c < 0) {
          best = j;
        } else if (j - lo > (hi - j)) {
          best = j;
        }
      }
    }
    if (best == 0) {
      out.add('GRID_$grid: ERR_INVALID_RANGE');
    } else {
      var h = data[best];
      if (h == 0) {
        out.add('GRID_$grid: ERR_FUTURE');
      } else {
        out.add('GRID_$grid: LEAD_$lead: AGE_$age: $gap');
      }
    }
    i = hi;
  }
  return out;
}

