    String bestMark = 'O';
    int bestScore = -1000000;

    for (String mark in ['X', 'O']) {
      int score = -1000000;
      for (var row in board) {
        for (var col in row) {
          if (col == ' ') {
            makeMove(row.indexOf(' '), col.indexOf(' '), mark);
            int currentScore = minimax(0, false);
            makeMove(row.indexOf(' '), col.indexOf(' '), ' ');
            if (currentScore > score) {
              score = currentScore;
            }
          }
        }
      }
      if (score > bestScore) {
        bestScore = score;
        bestMark = mark;
      }
    }

    makeMove(bestScore > -1000000 ? bestScore : -1, bestMark);
  }

  int minimax(int depth, bool isMaximizing) {
    if (hasWon(isMaximizing ? 'O' : 'X')) {
      return isMaximizing ? 10 : -10;
    }
    if (hasWon(isMaximizing ? 'X' : 'O')) {
      return isMaximizing ? -10 : 10;
    }
