      for (var row in board) {
        for (var col in row) {
          if (col == ' ') {
            makeMove(row.indexOf(' '), col.indexOf(' '), 'O');
            int eval = minimax(depth + 1, false);
            makeMove(row.indexOf(' '), col.indexOf(' '), ' ');
            if (eval > maxEval) {
              maxEval = eval;
            }
          }
        }
      }
      return maxEval;
    } else {
      int minEval = 1000000;
      for (var row in board) {
        for (var col in row) {
          if (col == ' ') {
            makeMove(row.indexOf(' '), col.indexOf(' '), 'X');
            int eval = minimax(depth + 1, true);
            makeMove(row.indexOf(' '), col.indexOf(' '), ' ');
