void fn0() {

  String jsonEncode(dynamic obj) {
    if (obj == null) {
      return 'null';
    } else if (obj is bool) {
      return obj ? 'true' : 'false';
    } else if (obj is num) {
      return obj.toString();
    } else if (obj is String) {
      String escaped = obj
          .replaceAll('\\', '\\\\')
          .replaceAll('"', '\\"')
          .replaceAll('\n', '\\n')
          .replaceAll('\r', '\\r')
          .replaceAll('\t', '\\t');
