List<List<double>> buildKdTree(List<List<double>> points, int k) {
  if (points.length <= 1) return [points];

  int axis = k % 3; 
  points.sort((a, b) {
    if (a[axis] != b[axis]) return a[axis].compareTo(b[axis]);
    return a[k % 3].compareTo(b[k % 3]);
  });

  int rootIndex = (points.length + 1) ~/ 2;
  List<List<double>> left = buildKdTree(points.sublist(0, rootIndex), k - 1);
  List<List<double>> right = buildKdTree(points.sublist(rootIndex), k - 1);

  return [
    ...left,
    ...right,
  ];
}

void printKdTree(List<List<double>> tree) {
  for (var node in tree) {
    print('Depth ${node[0]}: ${node[1]}');
    if (node[1] is List<List<double>>) {
      printKdTree(node[1]);
    }
  }
}

