class Node {
  final List<double> point;
  Node? left;
  Node? right;

  Node(this.point);
}

class KdTree {
  Node? root;

  void insert(Node node) {
    if (root == null) {
      root = node;
    } else {
      _insert(root, node);
    }
  }

  void _insert(Node? node, Node? newNode) {
    if (node == null) {
      newNode!.parent = node;
      return;
    }

    final int axis = newNode!.point[0] > node!.point[0]
        ? 0
        : (newNode!.point[0] == node!.point[0]
            ? 1
            : 2);

    final Node? child = node.point[axis] < newNode!.point[axis]
        ? node.left
        : node.right;

    if (child == null) {
      newNode.parent = node;
      if (axis == 0) {
        node.left = newNode;
      } else {
        node.right = newNode;
      }
    } else {
      _insert(child, newNode);
    }
  }

  void _printTree(Node? node, int depth) {
    if (node == null) return;
    print('Depth $depth: ${node.point}');
    _printTree(node.left, depth + 1);
    _printTree(node.right, depth + 1);
  }

  void printTree() {
    _printTree(root, 0);
  }
}

