List<int> fn0(List<int> data, int target) {
  if (data.isEmpty) return <int>[];
  final int n = data.length;
  final List<int> counts = List<int>.filled(n + 1, 0);
  for (int i = 0; i < n; i++) {
    counts[i + 1] = counts[i] + data[i];
  }
  final List<int> result = <int>[];
  for (int j = 0; j <= n; j++) {
    if (counts[j] >= target) {
      result.add(j);
    }
  }
  return result.reversed.toList();
}

