List<int> fn0(List<int> requests, int maxCapacity) {
  if (requests.isEmpty) return [];
  List<int> result = List<int>.filled(requests.length, 0);
  int current = 0;
  for (int i = 0; i < requests.length; i++) {
    if (requests[i] <= maxCapacity) {
      current = i;
      result[i] = current;
    } else {
      if (current > 0) {
        result[current - 1] = current;
        current = i;
        result[i] = current;
      }
    }
  }
  if (current < requests.length) {
    result[current] = current;
  }
  return result.reversed.toList();
}

