  print('Hint: Double-tap to go back, long-press to go home');
  print('==============================================');
  print('Navigation Statistics');
  print('==============================================');

  double calculateVelocity(Duration duration) {
    return duration.inMilliseconds / 1000.0;
  }

  int totalGestures = 0;
  int homeGestures = 0;
  int uniqueScreens = 0;
  int backGestures = 0;
  double averageVelocity = 0.0;
  int mostCommonGesture = 0;
  String? mostCommonGestureName;

  for (final gesture in gestures) {
    final name = gesture['name'] as String;
    final duration = gesture['duration'] as int;
    final velocity = calculateVelocity(Duration(milliseconds: duration));

    print('\nGesture detected: $name');
    print('   Gesture: ${name.split('_').join(" ")}');
    print('   Velocity: ${velocity.toStringAsFixed(2)} px/ms');

    if (name == 'swipe_left') {
      totalGestures++;
    } else if (name == 'swipe_right') {
      homeGestures++;
    } else if (name == 'swipe_up') {
      uniqueScreens++;
    } else if (name == 'swipe_down') {
      backGestures++;
    } else if (name == 'double_tap') {
      backGestures++;
    } else if (name == 'long_press') {
      homeGestures++;
    }

    if (mostCommonGesture == 0 || velocity > mostCommonGesture) {
      mostCommonGesture = velocity;
      mostCommonGestureName = name;
    }

    averageVelocity += velocity;
  }

  final entries = screens.entries.toList()..sort((a, b) => b.value.compareTo(a.value));

  print('\nNavigation efficiency: ${uniqueScreens / screens.length * 100.0} %');
  print('Total gestures performed: $totalGestures');
  print('Home navigations: $homeGestures');
  print('Back navigations: $backGestures');
