    print('Tip: ${mostCommonGestureName.split("_").join(" ")} is your most used gesture.');
    print('Tip: ${mostCommonGestureName} increases navigation efficiency by ${averageVelocity.toStringAsFixed(2)} px/ms.');
  } else {
    print('No navigation available for your current gestures.');
  }

  print('\nGesture frequency:');
  screens.forEach((screen) {
    final visits = entries.where((e) => e.key == screen.id).length;
    print('   ${screen.name}: ${visits} visits');
  });

  print('\nNavigation stack:');
  final stack = <String>[];
  for (var i = 0; i < entries.length; i++) {
    final entry = entries[i];
    if (entry.value == 'home') {
      if (stack.isNotEmpty) {
        stack.removeLast();
      }
    } else {
      stack.add(entry.key);
    }
  }

  print('  ${stack.join(", ")}');
  print('==============================================');
  print('Gesture Heatmap');
  print('==============================================');

  for (var i = 0; i < screens.length; i++) {
