    final x = (i % 10).toDouble();
    final y = (visits - (i % 10)) / 2.0;
    print('   ${screen.name}: ${visits} visits (${x}, $y)');
  }

  print('\nGesture-Based Navigation System');
  print('==============================================');
  print('Gesture-Based Navigation System');
  print('==============================================');
  print('Navigation session complete!');
