int binarySearch(List<int> list, int target) {
  int low = 0;
  int high = list.length - 1;
  int result = -1;

  while (low <= high) {
    int mid = low + (high - low) ~/ 2;
    if (list[mid] == target) {
      result = mid;
      break;
    } else if (list[mid] < target) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return result;
}

