  List<String> result = [];
  int i = 0;
  while (i < sequence.length) {
    int j = i;
    while (j < sequence.length && sequence[j] == sequence[i]) {
      j++;
    }
    String letter = sequence[i];
    int count = j - i;
    if (count > 1) {
      letter += count.toString();
    }
    result.add(letter);
    i = j;
  }
  return result;
}

