  List<int> stack = [];
  for (int i = 0; i < symbol.length; i++) {
    if (stack.isEmpty) {
      stack.add(i);
    } else if (stack.last != i) {
      stack.add(i);
    }
  }

  if (stack.isNotEmpty) return 'unclosed:${stack.length}';

  for (int start = 0; start < heights.length; start++) {
    int end = start + symbol.length;
