    for (int j = start; j < end; j++) {
      if (heights[j] != symbol.codeUnitAt(j)) {
        valid = false;
        break;
      }
    }
    if (valid) {
      int score = 0;
      int highest = heights[start];
      for (int j = start; j < end; j++) {
        int h = heights[j];
        if (h > highest) {
          score = -h;
        } else if (h < highest - tolerance) {
          score = h;
        }
      }
      if (score == 0) {
        return 'swing@$start:${end}';
      } else if (score > 0) {
        return 'mismatch@$start:${end}:$score';
      }
    }
  }

