void fn0() {

  int n = 8;
  List<List<int>> board = List.generate(n, (_) => List.filled(n, 0));

  bool isSafe(int row, int col, List<List<int>> board) {
    for (int i = 0; i < row; i++) {
      if (board[i][col] == 1) return false;
    }
    return true;
  }

  bool isSafe(List<List<int>> board, int row, int col, List<int> queens) {
    for (int q in queens) {
      if (board[row][q] == 1) return false;
    }
    return true;
  }

  void solve(List<List<int>> board, int row, List<int> queens, int solutions) {
    if (row == n) {
      print('Solution $solutions:');
      for (var row in board) {
        print(row.join(' '));
      }
      print('');
      solutions++;
      return;
    }
    for (int col = 0; col < n; col++) {
      if (isSafe(row, col, board)) {
        board[row][col] = 1;
        queens.add(col);
        solve(board, row + 1, queens, solutions);
        queens.removeLast();
        board[row][col] = 0;
      }
    }
  }

  int solutions = 0;
  solve(board, 0, [], solutions);
  print('Total solutions found: $solutions');

  print('N-Queens Solutions for 4x4 board:');
  n = 4;
  board = List.generate(n, (_) => List.filled(n, 0));
  solutions = 0;
  solve(board, 0, [], solutions);
}

