class Fitness {
  final int chromosomeLength;
  final String target;
  final Random random;

  Fitness(this.chromosomeLength, this.target, this.random);

  int fitness(String individual) {
    int fitness = 0;
    for (int i = 0; i < individual.length; i++) {
      if (individual[i] == target[i]) {
        fitness++;
      }
    }
    return fitness;
  }
}

class Individual {
  final int chromosomeLength;
  final List<String> bits;
  int fitness;

  Individual(this.chromosomeLength, [this.bits = const []]);

  String toBitString() {
    return bits.join('');
  }

  String toCharArray() {
    return bits.map((c) => c).join('');
  }

  void mutate() {
    for (int i = 0; i < bits.length; i++) {
      if (random.nextDouble() < mutationRate) {
        bits[i] = bits[i] == '0' ? '1' : '0';
      }
    }
  }
}

class Population {
  final int populationSize;
  final Random random;
  final List<Individual> individuals;

  Population(this.populationSize, this.random, [this.individuals = const []]);

  void generate(Fitness fitness) {
    while (individuals.length < populationSize) {
      var individual = Individual(
          chromosomeLength, List<String>.generate(
              chromosomeLength, (i) => random.nextInt().toString()));
      individual.fitness = fitness(individual.toBitString());
      individuals.add(individual);
    }
  }
}

class Tournament {
  final Random random;

  Tournament(this.random);

  Individual select(Population population) {
    final tournamentSize = 4;
    final tournament = <Individual>[];

    while (tournament.length < tournamentSize) {
      final i = random.nextInt(population.individuals.length);
      tournament.add(population.individuals[i]);
    }

    tournament.sort((a, b) => b.fitness - a.fitness);
    return tournament.first;
  }
}

