class GeneticAlgorithm {
  final Random rng;
  final String solution;
  int populationSize;
  int mutationRate;
  int generations;
  int eliteSize;
  int maxGenerations;

  GeneticAlgorithm(this.rng, this.solution, {this.populationSize = 100, this.mutationRate = 0.01, this.generations = 100, this.eliteSize = 20, this.maxGenerations = 10000});

  void run() {
    final List<Individual> population = List<Individual>.generate(populationSize, (index) {
      final String chromosome = rng.generate(solution.length, (i) => rng.nextInt(26) + 65);
      final fitness = chromosome.length - solution.length;
      return Individual(chromosome, fitness);
    });

    int generation = 0;
    while (generation < maxGenerations) {
      population.sort((a, b) => b.getScore().compareTo(a.getScore()));
      if (population.first.getScore() == 1) {
        print('Solution found in generation $generation!');
        break;
      }

      final List<Individual> elite = population.take(eliteSize).toList();
      population.clear();

      while (population.length < populationSize) {
        final Individual parent1 = elite[rng.nextInt(elite.length)];
        final Individual parent2 = elite[rng.nextInt(elite.length)];
        final Individual child = Individual(
          (parent1.chromosome as String) + (parent2.chromosome as String),
          rng.nextDouble() < mutationRate ? parent1.fitness + parent2.fitness : parent1.fitness,
        );
        population.add(child);
      }

      generation++;
    }

    if (generation == maxGenerations) {
      print('\nMax generations reached without finding exact solution.');
    } else {
      print('\n--- Final Statistics ---');
      print('Total generations: $generation');
      print('Population size: $populationSize');
      print('Mutation rate: $mutationRate');
      print('Elite size: $eliteSize');
      print('Best result: ${population.first.chromosome}');
      print('Fitness: ${population.first.fitness}');
      print('\nTop 5 individuals:');
      for (var i = 0; i < elite.length && i < 5; i++) {
        print('  ${i + 1}. ${elite[i].chromosome} (fitness: ${elite[i].fitness})');
      }
      print('Best individual: ${population.first.chromosome}');
      print('Fitness: ${population.first.fitness}');
      print('Average fitness: ${population.map((e) => e.fitness).reduce((a, b) => a + b) / population.length}');
    }
  }
}

