  if (amounts.isEmpty) return <String>[];

  List<double> scaled = amounts.map((a) => a * scaleFactor).toList();

  List<double> rounded = scaled.map((a) => a.roundToDouble()).toList();

  List<double> absolute = rounded.map((a) => a.abs()).toList();

  List<double> aboveThreshold = absolute.where((a) => a > threshold).toList();

  double sum = aboveThreshold.fold(0.0, (a, b) => a + b);

