class KMeans {
  double eps; 
  int k; 
  List<List<Point>> points; 

  KMeans(this.eps, this.k, this.points);

  List<Cluster> _cluster(List<Point> points) {
    final clusters = <Cluster>[];
    for (final point in points) {
      clusters.add(Cluster.fromList(point));
    }
    return clusters;
  }

  void _assignPoints(List<Cluster> clusters) {
    for (final cluster in clusters) {
      for (final point in cluster.points) {
        double minDist = 1000.0;
        final List<Cluster> neighbors = [];
        for (final other in clusters) {
          if (other == cluster) continue;
          final dist = (point.x - other.centerPoint().x).abs() +
                      (point.y - other.centerPoint().y).abs();
          if (dist < minDist) {
            minDist = dist;
            neighbors.add(other);
          }
        }
        if (neighbors.length > 1) {
          for (final neighbor in neighbors) {
            cluster.addPoint(neighbor.centerPoint());
          }
        } else if (neighbors.length == 0) {
          cluster.addPoint(Point(100.0, 100.0));
        }
      }
    }
  }

  void _updateClusters(List<Cluster> clusters) {
    for (var i = 0; i < clusters.length; i++) {
      final cluster = clusters[i];
      if (cluster.points.length < 2) continue;
      final newCenters = <Point>[];
      cluster.points.forEach((point) {
        final newX = (point.x + cluster.centerPoint().x) / 2.0;
        final newY = (point.y + cluster.centerPoint().y) / 2.0;
        newCenters.add(Point(newX, newY));
      });
      cluster.clusters = [];
      cluster.addPoints(newCenters);
    }
  }

  void _printCluster(Cluster cluster) {
    print('Cluster ${cluster.points.length}:');
    cluster.points.forEach((point) {
      print('  Point ${point.x}, ${point.y}');
    });
  }

  void _printNoise() {
    print('Noise:');
    final noise = clusters.where((c) => c.points.length == 1).toList();
    noise.forEach(_printCluster);
  }

  void _printSummary() {
    print('=' * 50);
    print('K-Means Clustering');
    print('=' * 50);
    print('eps: $eps');
    print('k: $k');
    _printNoise();
    print('=' * 50);
  }

  void run() {
    final clusters = _cluster(points);
    _assignPoints(clusters);
    _updateClusters(clusters);
    _printSummary();
  }
}

