      (_) => List<bool>.filled(maze[0].length, false),
    );
    final List<List<int>> queue = Queue<List<int>>();
    queue.add([start[0], start[1]]);
    visited[start[0]][start[1]] = true;
    int steps = 0;

    while (queue.isNotEmpty) {
      final List<int> current = queue.removeFirst();
      final int x = current[0];
      final int y = current[1];
      if (x == goal[0] && y == goal[1]) {
        print('Path found from [$x, $y] to [$goal[0], $goal[1]]!');
        print('Path length: $steps');
        return true;
      }

      for (final int d in const [1, -1, 2, -2]) {
        final int nx = x + d;
        final int ny = y + d;
        if (nx >= 0 && nx < maze.length && ny >= 0 && ny < maze[nx].length) {
          if (!visited[nx][ny]) {
            visited[nx][ny] = true;
            if (maze[nx][ny] == 0) {
              queue.add([nx, ny]);
              steps++;
            }
          }
        }
      }
    }
    print('No path found from [$start[0], $start[1]] to [$goal[0], $goal[1]]!');
