          if (ni >= 0 && ni < size && nj >= 0 && nj < size) {
            if (maze[ni][nj] == 0) {
              maze[i][j] = 1;
              maze[ni][nj] = 1;
              break;
            }
          }
        }
      }
    }
    return maze;
  }

