void fn0() {

  List<int> coins = [1, 2, 5];
  int amount = 11;

  int countWays(List<int> coins, int amount) {
    if (amount == 0) return 1;
    if (coins.isEmpty) return 0;

    List<List<int>> dp = List.generate(amount + 1, (_) => List<int>.filled(amount + 1, 0));

    for (int i = 1; i <= amount; i++) {
      for (int j = 0; j < i; j++) {
        int coin = coins[j];
        if (coin <= 0) continue;
        if (j >= i - coin) {
          dp[i][j] = dp[i - coin][j];
        } else {
          int best = dp[i - coin][j];
          int secondBest = dp[i - coin][j - coin];
          dp[i][j] = best > secondBest ? best : secondBest;
        }
      }
    }
    return dp[amount][amount];
  }

  print('Coin Change Problem Implementation');
  print('=' * 50);
  print('Coins available: $coins');
  print('Target amount: $amount');
  print('=' * 50);
  print('Number of ways to make change: ${countWays(coins, amount)}');

  print('\n==================================\n');

  coins = [1, 2, 5];
  amount = 5;
  print('Coins: [1, 2, 5], Amount: $amount => ${countWays(coins, amount)} ways');

  coins = [1, 5, 10, 25];
  amount = 10;
