  List<double> dp = List<double>.filled(n + 1, 0.0);
  dp[0] = 1.0;

  for (int i = 1; i <= n; i++) {
    int sum = 0;
    for (int j = i; j >= 1; j--) {
      sum += packets[j - 1];
      if (sum > mtu) break;
      dp[i] += dp[j - 1];
    }
  }

  return dp[n] / n;
}

