int combinationsCount(List<T> items, int k) {
  if (k < 0 || k > items.length) return 0;
  if (k == 0) return 1;
  int count = 0;
  for (int i = 0; i <= items.length - k; i++) {
    bool allDistinct = true;
    for (int j = i + 1; j <= items.length - k; j++) {
      if (items[i] == items[j]) {
        allDistinct = false;
        break;
      }
    }
    if (allDistinct) count++;
  }
  return count;
}

