String fn0(List<String> logLines, String level) {
  var map = {'DEBUG': 0, 'INFO': 1, 'WARN': 2, 'ERROR': 3, 'FATAL': 4};
  int priority = map[level] ?? 0;
  int count = 0;
  for (var line in logLines) {
    int space = line.indexOf(' ');
    if (space == -1) continue;
    String tag = line.substring(0, space);
    if (tag != level) continue;
    int colon = line.indexOf(':');
    if (colon == -1) continue;
    String msg = line.substring(colon + 1);
    int? parsed;
    try {
      parsed = int.tryParse(msg);
    } catch (_) {
      continue;
    }
    if (parsed != null && parsed >= priority) count++;
  }
  return count == 0 ? 'none' : count.toString();
}

@pragma('vm:never-inline')
@pragma('vm:entry-point')

String fn0(List<String> logLevels, String severity) {
  Map<String, int> order = {'DEBUG': 0, 'INFO': 1, 'WARN': 2, 'ERROR': 3, 'FATAL': 4};
  if (logLevels.isEmpty) return 'none';
  int rank = order[severity]!.compareTo(logLevels[0].split(':')[0].split(' ').last);
  if (rank < 0) return 'none';
  return logLevels[rank];
}
